static void luna_print_usage(FILE *stream) {
    (void)fputs("usage: lunac [--target triple] [--emit check|ir|asm] "
                "[-o path] input.luna\n"
                "\n"
                "targets:\n"
                "  x86_64-unknown-linux-gnu (default)\n"
                "\n"
                "options:\n"
                "  --target name  select the compilation target\n"
                "  --emit check   parse, type-check and verify IR\n"
                "  --emit ir      write textual Luna IR\n"
                "  --emit asm     write x86-64 GNU assembly (default)\n"
                "  -o path        output path; '-' writes to stdout\n"
                "  --version      print compiler version\n"
                "  --help         print this help\n",
                stream);
}

static bool luna_parse_emit_kind(const char *name, LunaEmitKind *emit_kind) {
    if (strcmp(name, "check") == 0) {
        *emit_kind = LUNA_EMIT_CHECK;
        return true;
    }
    if (strcmp(name, "ir") == 0) {
        *emit_kind = LUNA_EMIT_IR;
        return true;
    }
    if (strcmp(name, "asm") == 0) {
        *emit_kind = LUNA_EMIT_ASSEMBLY;
        return true;
    }
    return false;
}

int main(int argument_count, char **arguments) {
    LunaCompilerOptions options = {
        .input_path = NULL,
        .output_path = NULL,
        .emit_kind = LUNA_EMIT_ASSEMBLY,
        .target = luna_target_info_default(),
    };

    for (int index = 1; index < argument_count; index += 1) {
        const char *argument = arguments[index];

        if (strcmp(argument, "--help") == 0) {
            luna_print_usage(stdout);
            return 0;
        }

        if (strcmp(argument, "--version") == 0) {
            (void)puts("lunac 0.1.0-dev");
            return 0;
        }

        if (strcmp(argument, "--emit") == 0) {
            if (index + 1 >= argument_count ||
                !luna_parse_emit_kind(arguments[index + 1],
                                      &options.emit_kind)) {
                (void)fputs("error: --emit requires check, ir or asm\n",
                            stderr);
                return 2;
            }
            index += 1;
            continue;
        }

        if (strcmp(argument, "--target") == 0) {
            if (index + 1 >= argument_count) {
                (void)fputs("error: --target requires a target triple\n",
                            stderr);
                return 2;
            }
            options.target = luna_target_info_from_triple(arguments[index + 1]);
            if (options.target == NULL) {
                (void)fprintf(stderr, "error: unsupported target '%s'\n",
                              arguments[index + 1]);
                return 2;
            }
            index += 1;
            continue;
        }

        if (strcmp(argument, "-o") == 0) {
            if (index + 1 >= argument_count) {
                (void)fputs("error: -o requires an output path\n", stderr);
                return 2;
            }
            options.output_path = arguments[index + 1];
            index += 1;
            continue;
        }

        if (argument[0] == '-') {
            (void)fprintf(stderr, "error: unknown option '%s'\n", argument);
            return 2;
        }

        if (options.input_path != NULL) {
            (void)fputs(
                "error: the bootstrap compiler accepts exactly one source "
                "unit\n",
                stderr);
            return 2;
        }
        options.input_path = argument;
    }

    if (options.input_path == NULL) {
        luna_print_usage(stderr);
        return 2;
    }

    if (options.emit_kind != LUNA_EMIT_CHECK && options.output_path == NULL) {
        options.output_path =
            options.emit_kind == LUNA_EMIT_IR ? "a.lir" : "a.s";
    }

    return luna_compile(&options, stderr);
}

#include "luna/frontend/diagnostic/diagnostic.h"

#include <stdarg.h>

static void luna_diagnostic_print_source_line(FILE *stream,
                                              LunaSourceSpan span) {
    if (span.source == NULL || span.offset > span.source->length) {
        return;
    }

    size_t line_start = span.offset;
    while (line_start > 0U && span.source->text[line_start - 1U] != '\n') {
        line_start -= 1U;
    }

    size_t line_end = span.offset;
    while (line_end < span.source->length &&
           span.source->text[line_end] != '\n') {
        line_end += 1U;
    }

    (void)fputs("  ", stream);
    (void)fwrite(span.source->text + line_start, 1U, line_end - line_start,
                 stream);
    (void)fputc('\n', stream);
    (void)fputs("  ", stream);

    const size_t caret_column = span.offset - line_start;
    for (size_t index = 0U; index < caret_column; index += 1U) {
        const char character = span.source->text[line_start + index];
        (void)fputc(character == '\t' ? '\t' : ' ', stream);
    }

    const size_t available = line_end - span.offset;
    size_t caret_count = span.length == 0U ? 1U : span.length;
    if (available == 0U) {
        caret_count = 1U;
    } else if (caret_count > available) {
        caret_count = available;
    }
    for (size_t index = 0U; index < caret_count; index += 1U) {
        (void)fputc('^', stream);
    }
    (void)fputc('\n', stream);
}

void luna_diagnostic_init(LunaDiagnosticEngine *diagnostics, FILE *stream) {
    diagnostics->stream = stream == NULL ? stderr : stream;
    diagnostics->error_count = 0U;
}

void luna_diagnostic_error(LunaDiagnosticEngine *diagnostics,
                           LunaSourceSpan span, const char *format, ...) {
    diagnostics->error_count += 1U;

    const char *path = span.source == NULL || span.source->path == NULL
                           ? "<unknown>"
                           : span.source->path;
    (void)fprintf(diagnostics->stream, "%s:%u:%u: error: ", path, span.line,
                  span.column);

    va_list arguments;
    va_start(arguments, format);
    (void)vfprintf(diagnostics->stream, format, arguments);
    va_end(arguments);
    (void)fputc('\n', diagnostics->stream);

    luna_diagnostic_print_source_line(diagnostics->stream, span);
}

void luna_diagnostic_error_plain(LunaDiagnosticEngine *diagnostics,
                                 const char *format, ...) {
    diagnostics->error_count += 1U;
    (void)fputs("error: ", diagnostics->stream);

    va_list arguments;
    va_start(arguments, format);
    (void)vfprintf(diagnostics->stream, format, arguments);
    va_end(arguments);
    (void)fputc('\n', diagnostics->stream);
}

size_t luna_diagnostic_error_count(const LunaDiagnosticEngine *diagnostics) {
    return diagnostics->error_count;
}

