typedef struct LunaKeyword {
    const char *text;
    LunaTokenKind kind;
} LunaKeyword;

static const LunaKeyword luna_keywords[] = {
    {"alignof", LUNA_TOKEN_ALIGNOF},
    {"as", LUNA_TOKEN_AS},
    {"bool", LUNA_TOKEN_BOOL},
    {"break", LUNA_TOKEN_BREAK},
    {"case", LUNA_TOKEN_CASE},
    {"const", LUNA_TOKEN_CONST},
    {"continue", LUNA_TOKEN_CONTINUE},
    {"default", LUNA_TOKEN_DEFAULT},
    {"do", LUNA_TOKEN_DO},
    {"else", LUNA_TOKEN_ELSE},
    {"enum", LUNA_TOKEN_ENUM},
    {"export", LUNA_TOKEN_EXPORT},
    {"extern", LUNA_TOKEN_EXTERN},
    {"f32", LUNA_TOKEN_F32},
    {"f64", LUNA_TOKEN_F64},
    {"false", LUNA_TOKEN_FALSE},
    {"fn", LUNA_TOKEN_FN},
    {"for", LUNA_TOKEN_FOR},
    {"i16", LUNA_TOKEN_I16},
    {"i32", LUNA_TOKEN_I32},
    {"i64", LUNA_TOKEN_I64},
    {"i8", LUNA_TOKEN_I8},
    {"if", LUNA_TOKEN_IF},
    {"import", LUNA_TOKEN_IMPORT},
    {"isize", LUNA_TOKEN_ISIZE},
    {"let", LUNA_TOKEN_LET},
    {"module", LUNA_TOKEN_MODULE},
    {"null", LUNA_TOKEN_NULL},
    {"offsetof", LUNA_TOKEN_OFFSETOF},
    {"return", LUNA_TOKEN_RETURN},
    {"sizeof", LUNA_TOKEN_SIZEOF},
    {"struct", LUNA_TOKEN_STRUCT},
    {"switch", LUNA_TOKEN_SWITCH},
    {"true", LUNA_TOKEN_TRUE},
    {"u16", LUNA_TOKEN_U16},
    {"u32", LUNA_TOKEN_U32},
    {"u64", LUNA_TOKEN_U64},
    {"u8", LUNA_TOKEN_U8},
    {"union", LUNA_TOKEN_UNION},
    {"usize", LUNA_TOKEN_USIZE},
    {"var", LUNA_TOKEN_VAR},
    {"void", LUNA_TOKEN_VOID},
    {"while", LUNA_TOKEN_WHILE},
};

static bool luna_is_ascii_letter(char character) {
    return (character >= 'a' && character <= 'z') ||
           (character >= 'A' && character <= 'Z');
}

static bool luna_is_decimal_digit(char character) {
    return character >= '0' && character <= '9';
}

static bool luna_is_hex_digit(char character) {
    return luna_is_decimal_digit(character) ||
           (character >= 'a' && character <= 'f') ||
           (character >= 'A' && character <= 'F');
}

static bool luna_lexer_at_end(const LunaLexer *lexer) {
    return lexer->offset >= lexer->source->length;
}

static char luna_lexer_peek(const LunaLexer *lexer) {
    if (luna_lexer_at_end(lexer)) {
        return '\0';
    }
    return lexer->source->text[lexer->offset];
}

static char luna_lexer_peek_next(const LunaLexer *lexer) {
    if (lexer->offset + 1U >= lexer->source->length) {
        return '\0';
    }
    return lexer->source->text[lexer->offset + 1U];
}

static char luna_lexer_advance(LunaLexer *lexer) {
    const char character = luna_lexer_peek(lexer);
    if (character == '\0' && luna_lexer_at_end(lexer)) {
        return '\0';
    }

    lexer->offset += 1U;
    if (character == '\n') {
        lexer->line += 1U;
        lexer->column = 1U;
    } else {
        lexer->column += 1U;
    }
    return character;
}

static bool luna_lexer_match(LunaLexer *lexer, char expected) {
    if (luna_lexer_peek(lexer) != expected) {
        return false;
    }

    (void)luna_lexer_advance(lexer);
    return true;
}

static LunaToken luna_lexer_make_token(const LunaLexer *lexer,
                                       LunaTokenKind kind, size_t start_offset,
                                       uint32_t start_line,
                                       uint32_t start_column) {
    return (LunaToken){
        .kind = kind,
        .span =
            {
                .source = lexer->source,
                .offset = start_offset,
                .length = lexer->offset - start_offset,
                .line = start_line,
                .column = start_column,
            },
    };
}

static void luna_lexer_skip_trivia(LunaLexer *lexer) {
    for (;;) {
        const char character = luna_lexer_peek(lexer);

        if (character == ' ' || character == '\t' || character == '\r' ||
            character == '\n') {
            (void)luna_lexer_advance(lexer);
            continue;
        }

        if (character == '/' && luna_lexer_peek_next(lexer) == '/') {
            while (!luna_lexer_at_end(lexer) &&
                   luna_lexer_peek(lexer) != '\n') {
                (void)luna_lexer_advance(lexer);
            }
            continue;
        }

        if (character == '/' && luna_lexer_peek_next(lexer) == '*') {
            const size_t start_offset = lexer->offset;
            const uint32_t start_line = lexer->line;
            const uint32_t start_column = lexer->column;
            (void)luna_lexer_advance(lexer);
            (void)luna_lexer_advance(lexer);

            while (!luna_lexer_at_end(lexer) &&
                   !(luna_lexer_peek(lexer) == '*' &&
                     luna_lexer_peek_next(lexer) == '/')) {
                (void)luna_lexer_advance(lexer);
            }

            if (luna_lexer_at_end(lexer)) {
                LunaSourceSpan span = {
                    .source = lexer->source,
                    .offset = start_offset,
                    .length = lexer->offset - start_offset,
                    .line = start_line,
                    .column = start_column,
                };
                luna_diagnostic_error(lexer->diagnostics, span,
                                      "unterminated block comment");
                return;
            }

            (void)luna_lexer_advance(lexer);
            (void)luna_lexer_advance(lexer);
            continue;
        }

        return;
    }
}

static LunaTokenKind luna_lexer_identifier_kind(const LunaSourceFile *source,
                                                size_t start, size_t length) {
    const LunaStringView identifier =
        luna_string_view(source->text + start, length);

    const size_t keyword_count =
        sizeof(luna_keywords) / sizeof(luna_keywords[0]);
    for (size_t index = 0U; index < keyword_count; index += 1U) {
        if (luna_string_view_equal_c_string(identifier,
                                            luna_keywords[index].text)) {
            return luna_keywords[index].kind;
        }
    }

    return LUNA_TOKEN_IDENTIFIER;
}

static LunaToken luna_lexer_scan_identifier(LunaLexer *lexer,
                                            size_t start_offset,
                                            uint32_t start_line,
                                            uint32_t start_column) {
    while (luna_is_ascii_letter(luna_lexer_peek(lexer)) ||
           luna_is_decimal_digit(luna_lexer_peek(lexer)) ||
           luna_lexer_peek(lexer) == '_') {
        (void)luna_lexer_advance(lexer);
    }

    const LunaTokenKind kind = luna_lexer_identifier_kind(
        lexer->source, start_offset, lexer->offset - start_offset);
    return luna_lexer_make_token(lexer, kind, start_offset, start_line,
                                 start_column);
}

static bool luna_digit_matches_base(char character, unsigned int base) {
    switch (base) {
    case 2U:
        return character == '0' || character == '1';
    case 8U:
        return character >= '0' && character <= '7';
    case 10U:
        return luna_is_decimal_digit(character);
    case 16U:
        return luna_is_hex_digit(character);
    default:
        return false;
    }
}

static LunaToken luna_lexer_scan_number(LunaLexer *lexer, size_t start_offset,
                                        uint32_t start_line,
                                        uint32_t start_column) {
    unsigned int base = 10U;
    bool is_float = false;

    if (lexer->source->text[start_offset] == '0' &&
        (luna_lexer_peek(lexer) == 'b' || luna_lexer_peek(lexer) == 'B')) {
        base = 2U;
        (void)luna_lexer_advance(lexer);
    } else if (lexer->source->text[start_offset] == '0' &&
               (luna_lexer_peek(lexer) == 'o' ||
                luna_lexer_peek(lexer) == 'O')) {
        base = 8U;
        (void)luna_lexer_advance(lexer);
    } else if (lexer->source->text[start_offset] == '0' &&
               (luna_lexer_peek(lexer) == 'x' ||
                luna_lexer_peek(lexer) == 'X')) {
        base = 16U;
        (void)luna_lexer_advance(lexer);
    }

    while (luna_digit_matches_base(luna_lexer_peek(lexer), base) ||
           luna_lexer_peek(lexer) == '_') {
        (void)luna_lexer_advance(lexer);
    }

    if (base == 10U && luna_lexer_peek(lexer) == '.' &&
        luna_is_decimal_digit(luna_lexer_peek_next(lexer))) {
        is_float = true;
        (void)luna_lexer_advance(lexer);
        while (luna_is_decimal_digit(luna_lexer_peek(lexer)) ||
               luna_lexer_peek(lexer) == '_') {
            (void)luna_lexer_advance(lexer);
        }
    }

    if (base == 10U &&
        (luna_lexer_peek(lexer) == 'e' || luna_lexer_peek(lexer) == 'E')) {
        is_float = true;
        (void)luna_lexer_advance(lexer);
        if (luna_lexer_peek(lexer) == '+' || luna_lexer_peek(lexer) == '-') {
            (void)luna_lexer_advance(lexer);
        }
        while (luna_is_decimal_digit(luna_lexer_peek(lexer)) ||
               luna_lexer_peek(lexer) == '_') {
            (void)luna_lexer_advance(lexer);
        }
    }

    return luna_lexer_make_token(
        lexer, is_float ? LUNA_TOKEN_FLOAT : LUNA_TOKEN_INTEGER, start_offset,
        start_line, start_column);
}

static LunaToken luna_lexer_scan_quoted(LunaLexer *lexer, char quote,
                                        LunaTokenKind kind, size_t start_offset,
                                        uint32_t start_line,
                                        uint32_t start_column) {
    bool terminated = false;

    while (!luna_lexer_at_end(lexer)) {
        const char character = luna_lexer_advance(lexer);

        if (character == quote) {
            terminated = true;
            break;
        }

        if (character == '\\' && !luna_lexer_at_end(lexer)) {
            (void)luna_lexer_advance(lexer);
            continue;
        }

        if (character == '\n') {
            break;
        }
    }

    LunaToken token =
        luna_lexer_make_token(lexer, terminated ? kind : LUNA_TOKEN_INVALID,
                              start_offset, start_line, start_column);

    if (!terminated) {
        luna_diagnostic_error(lexer->diagnostics, token.span, "unterminated %s",
                              kind == LUNA_TOKEN_STRING ? "string literal"
                                                        : "character literal");
    }

    return token;
}

void luna_lexer_init(LunaLexer *lexer, const LunaSourceFile *source,
                     LunaDiagnosticEngine *diagnostics) {
    lexer->source = source;
    lexer->diagnostics = diagnostics;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
}

LunaToken luna_lexer_next(LunaLexer *lexer) {
    luna_lexer_skip_trivia(lexer);

    const size_t start_offset = lexer->offset;
    const uint32_t start_line = lexer->line;
    const uint32_t start_column = lexer->column;

    if (luna_lexer_at_end(lexer)) {
        return luna_lexer_make_token(lexer, LUNA_TOKEN_END, start_offset,
                                     start_line, start_column);
    }

    const char character = luna_lexer_advance(lexer);
    if (luna_is_ascii_letter(character) || character == '_') {
        return luna_lexer_scan_identifier(lexer, start_offset, start_line,
                                          start_column);
    }

    if (luna_is_decimal_digit(character)) {
        return luna_lexer_scan_number(lexer, start_offset, start_line,
                                      start_column);
    }

    LunaTokenKind kind = LUNA_TOKEN_INVALID;
    switch (character) {
    case '(':
        kind = LUNA_TOKEN_LEFT_PAREN;
        break;
    case ')':
        kind = LUNA_TOKEN_RIGHT_PAREN;
        break;
    case '{':
        kind = LUNA_TOKEN_LEFT_BRACE;
        break;
    case '}':
        kind = LUNA_TOKEN_RIGHT_BRACE;
        break;
    case '[':
        kind = LUNA_TOKEN_LEFT_BRACKET;
        break;
    case ']':
        kind = LUNA_TOKEN_RIGHT_BRACKET;
        break;
    case ',':
        kind = LUNA_TOKEN_COMMA;
        break;
    case '.':
        kind = LUNA_TOKEN_DOT;
        break;
    case ';':
        kind = LUNA_TOKEN_SEMICOLON;
        break;
    case ':':
        kind = LUNA_TOKEN_COLON;
        break;
    case '?':
        kind = LUNA_TOKEN_QUESTION;
        break;
    case '~':
        kind = LUNA_TOKEN_TILDE;
        break;

    case '+':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_PLUS_EQUAL
                                            : LUNA_TOKEN_PLUS;
        break;

    case '-':
        if (luna_lexer_match(lexer, '>')) {
            kind = LUNA_TOKEN_ARROW;
        } else if (luna_lexer_match(lexer, '=')) {
            kind = LUNA_TOKEN_MINUS_EQUAL;
        } else {
            kind = LUNA_TOKEN_MINUS;
        }
        break;

    case '*':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_STAR_EQUAL
                                            : LUNA_TOKEN_STAR;
        break;

    case '/':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_SLASH_EQUAL
                                            : LUNA_TOKEN_SLASH;
        break;

    case '%':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_PERCENT_EQUAL
                                            : LUNA_TOKEN_PERCENT;
        break;

    case '&':
        if (luna_lexer_match(lexer, '&')) {
            kind = LUNA_TOKEN_LOGICAL_AND;
        } else if (luna_lexer_match(lexer, '=')) {
            kind = LUNA_TOKEN_AMPERSAND_EQUAL;
        } else {
            kind = LUNA_TOKEN_AMPERSAND;
        }
        break;

    case '|':
        if (luna_lexer_match(lexer, '|')) {
            kind = LUNA_TOKEN_LOGICAL_OR;
        } else if (luna_lexer_match(lexer, '=')) {
            kind = LUNA_TOKEN_PIPE_EQUAL;
        } else {
            kind = LUNA_TOKEN_PIPE;
        }
        break;

    case '^':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_CARET_EQUAL
                                            : LUNA_TOKEN_CARET;
        break;

    case '!':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_BANG_EQUAL
                                            : LUNA_TOKEN_BANG;
        break;

    case '=':
        kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_EQUAL_EQUAL
                                            : LUNA_TOKEN_EQUAL;
        break;

    case '<':
        if (luna_lexer_match(lexer, '<')) {
            kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_SHIFT_LEFT_EQUAL
                                                : LUNA_TOKEN_SHIFT_LEFT;
        } else {
            kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_LESS_EQUAL
                                                : LUNA_TOKEN_LESS;
        }
        break;

    case '>':
        if (luna_lexer_match(lexer, '>')) {
            kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_SHIFT_RIGHT_EQUAL
                                                : LUNA_TOKEN_SHIFT_RIGHT;
        } else {
            kind = luna_lexer_match(lexer, '=') ? LUNA_TOKEN_GREATER_EQUAL
                                                : LUNA_TOKEN_GREATER;
        }
        break;

    case '"':
        return luna_lexer_scan_quoted(lexer, '"', LUNA_TOKEN_STRING,
                                      start_offset, start_line, start_column);

    case '\'':
        return luna_lexer_scan_quoted(lexer, '\'', LUNA_TOKEN_CHARACTER,
                                      start_offset, start_line, start_column);

    default:
        break;
    }

    LunaToken token = luna_lexer_make_token(lexer, kind, start_offset,
                                            start_line, start_column);

    if (kind == LUNA_TOKEN_INVALID) {
        luna_diagnostic_error(lexer->diagnostics, token.span,
                              "unexpected character");
    }

    return token;
}

#include "luna/frontend/parser/parser.h"

#include <limits.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

static const uint32_t luna_parser_max_nesting_depth = 256U;

static bool luna_parser_enter_nesting(LunaParser *parser, LunaSourceSpan span) {
    if (parser->nesting_depth >= luna_parser_max_nesting_depth) {
        luna_diagnostic_error(parser->diagnostics, span,
                              "maximum parser nesting depth exceeded");
        return false;
    }

    parser->nesting_depth += 1U;
    return true;
}

static void luna_parser_leave_nesting(LunaParser *parser) {
    parser->nesting_depth -= 1U;
}

static void *luna_parser_allocate(LunaParser *parser, size_t size,
                                  size_t alignment) {
    void *allocation = luna_arena_allocate_zero(parser->arena, size, alignment);
    if (allocation == NULL) {
        luna_diagnostic_error_plain(parser->diagnostics,
                                    "out of memory while parsing");
    }
    return allocation;
}

static LunaStringView luna_parser_token_text(LunaToken token) {
    return luna_source_span_text(token.span);
}

static LunaSourceSpan luna_parser_join_spans(LunaSourceSpan first,
                                             LunaSourceSpan last) {
    if (first.source == NULL || first.source != last.source) {
        return first;
    }

    const size_t last_end = last.offset + last.length;
    return (LunaSourceSpan){
        .source = first.source,
        .offset = first.offset,
        .length = last_end >= first.offset ? last_end - first.offset : 0U,
        .line = first.line,
        .column = first.column,
    };
}

static void luna_parser_advance(LunaParser *parser) {
    parser->previous = parser->current;
    do {
        parser->current = luna_lexer_next(&parser->lexer);
    } while (parser->current.kind == LUNA_TOKEN_INVALID);
}

static bool luna_parser_check(const LunaParser *parser, LunaTokenKind kind) {
    return parser->current.kind == kind;
}

static bool luna_parser_match(LunaParser *parser, LunaTokenKind kind) {
    if (!luna_parser_check(parser, kind)) {
        return false;
    }

    luna_parser_advance(parser);
    return true;
}

static bool luna_parser_expect(LunaParser *parser, LunaTokenKind kind,
                               const char *context) {
    if (luna_parser_match(parser, kind)) {
        return true;
    }

    luna_diagnostic_error(parser->diagnostics, parser->current.span,
                          "expected %s %s, found %s",
                          luna_token_kind_name(kind), context,
                          luna_token_kind_name(parser->current.kind));
    return false;
}

static LunaTypeRef luna_parser_parse_type(LunaParser *parser) {
    const LunaToken token = parser->current;
    LunaTypeKind kind = LUNA_TYPE_INVALID;

    switch (token.kind) {
    case LUNA_TOKEN_BOOL:
        kind = LUNA_TYPE_BOOL;
        break;
    case LUNA_TOKEN_I8:
        kind = LUNA_TYPE_I8;
        break;
    case LUNA_TOKEN_I16:
        kind = LUNA_TYPE_I16;
        break;
    case LUNA_TOKEN_I32:
        kind = LUNA_TYPE_I32;
        break;
    case LUNA_TOKEN_I64:
        kind = LUNA_TYPE_I64;
        break;
    case LUNA_TOKEN_ISIZE:
        kind = LUNA_TYPE_ISIZE;
        break;
    case LUNA_TOKEN_U8:
        kind = LUNA_TYPE_U8;
        break;
    case LUNA_TOKEN_U16:
        kind = LUNA_TYPE_U16;
        break;
    case LUNA_TOKEN_U32:
        kind = LUNA_TYPE_U32;
        break;
    case LUNA_TOKEN_U64:
        kind = LUNA_TYPE_U64;
        break;
    case LUNA_TOKEN_USIZE:
        kind = LUNA_TYPE_USIZE;
        break;
    case LUNA_TOKEN_F32:
        kind = LUNA_TYPE_F32;
        break;
    case LUNA_TOKEN_F64:
        kind = LUNA_TYPE_F64;
        break;
    case LUNA_TOKEN_VOID:
        kind = LUNA_TYPE_VOID;
        break;

    default:
        luna_diagnostic_error(parser->diagnostics, token.span,
                              "expected a type, found %s",
                              luna_token_kind_name(token.kind));
        return (LunaTypeRef){
            .kind = LUNA_TYPE_INVALID,
            .span = token.span,
        };
    }

    luna_parser_advance(parser);
    return (LunaTypeRef){
        .kind = kind,
        .span = token.span,
    };
}

static bool luna_parser_parse_integer(LunaParser *parser, LunaToken token,
                                      uint64_t *value) {
    const LunaStringView text = luna_parser_token_text(token);
    size_t index = 0U;
    uint64_t base = 10U;

    if (text.length >= 2U && text.data[0] == '0') {
        switch (text.data[1]) {
        case 'b':
        case 'B':
            base = 2U;
            index = 2U;
            break;
        case 'o':
        case 'O':
            base = 8U;
            index = 2U;
            break;
        case 'x':
        case 'X':
            base = 16U;
            index = 2U;
            break;
        default:
            break;
        }
    }

    uint64_t result = 0U;
    bool saw_digit = false;
    bool previous_was_separator = false;

    for (; index < text.length; index += 1U) {
        const char character = text.data[index];
        if (character == '_') {
            if (!saw_digit || previous_was_separator) {
                luna_diagnostic_error(
                    parser->diagnostics, token.span,
                    "invalid digit separator in integer literal");
                return false;
            }
            previous_was_separator = true;
            continue;
        }

        uint64_t digit = 0U;
        if (character >= '0' && character <= '9') {
            digit = (uint64_t)(unsigned int)(character - '0');
        } else if (character >= 'a' && character <= 'f') {
            digit = (uint64_t)(unsigned int)(character - 'a' + 10);
        } else if (character >= 'A' && character <= 'F') {
            digit = (uint64_t)(unsigned int)(character - 'A' + 10);
        } else {
            luna_diagnostic_error(parser->diagnostics, token.span,
                                  "invalid digit in integer literal");
            return false;
        }

        if (digit >= base) {
            luna_diagnostic_error(parser->diagnostics, token.span,
                                  "digit is not valid for base %llu",
                                  (unsigned long long)base);
            return false;
        }

        if (result > (UINT64_MAX - digit) / base) {
            luna_diagnostic_error(parser->diagnostics, token.span,
                                  "integer literal is too large");
            return false;
        }
        result *= base;
        result += digit;
        saw_digit = true;
        previous_was_separator = false;
    }

    if (!saw_digit || previous_was_separator) {
        luna_diagnostic_error(parser->diagnostics, token.span,
                              "invalid integer literal");
        return false;
    }

    *value = result;
    return true;
}

static bool luna_parser_scan_float_digits(LunaStringView text, size_t *index) {
    bool saw_digit = false;
    bool previous_was_separator = false;

    while (*index < text.length) {
        const char character = text.data[*index];
        if (character >= '0' && character <= '9') {
            saw_digit = true;
            previous_was_separator = false;
            *index += 1U;
            continue;
        }
        if (character == '_') {
            if (!saw_digit || previous_was_separator ||
                *index + 1U >= text.length || text.data[*index + 1U] < '0' ||
                text.data[*index + 1U] > '9') {
                return false;
            }
            previous_was_separator = true;
            *index += 1U;
            continue;
        }
        break;
    }

    return saw_digit && !previous_was_separator;
}

static bool luna_parser_validate_float(LunaParser *parser, LunaToken token) {
    const LunaStringView text = luna_parser_token_text(token);
    size_t index = 0U;
    bool has_fraction = false;
    bool has_exponent = false;

    bool valid = luna_parser_scan_float_digits(text, &index);
    if (valid && index < text.length && text.data[index] == '.') {
        has_fraction = true;
        index += 1U;
        valid = luna_parser_scan_float_digits(text, &index);
    }

    if (valid && index < text.length &&
        (text.data[index] == 'e' || text.data[index] == 'E')) {
        has_exponent = true;
        index += 1U;
        if (index < text.length &&
            (text.data[index] == '+' || text.data[index] == '-')) {
            index += 1U;
        }
        valid = luna_parser_scan_float_digits(text, &index);
    }

    valid = valid && (has_fraction || has_exponent) && index == text.length;
    if (!valid) {
        luna_diagnostic_error(parser->diagnostics, token.span,
                              "invalid floating-point literal");
    }
    return valid;
}

static LunaExpression *luna_parser_parse_expression(LunaParser *parser);

static LunaExpression *luna_parser_new_expression(LunaParser *parser,
                                                  LunaExpressionKind kind,
                                                  LunaSourceSpan span) {
    LunaExpression *expression = luna_parser_allocate(
        parser, sizeof(LunaExpression), _Alignof(LunaExpression));
    if (expression == NULL) {
        return NULL;
    }

    expression->kind = kind;
    expression->span = span;
    expression->checked_type = LUNA_TYPE_INVALID;
    return expression;
}

static LunaExpression *luna_parser_parse_call(LunaParser *parser,
                                              LunaToken name_token) {
    LunaExpression *call = luna_parser_new_expression(
        parser, LUNA_EXPRESSION_CALL, name_token.span);
    if (call == NULL) {
        return NULL;
    }

    call->as.call.name = luna_parser_token_text(name_token);
    LunaExpression **next_argument = &call->as.call.first_argument;
    if (!luna_parser_enter_nesting(parser, name_token.span)) {
        return call;
    }

    if (!luna_parser_check(parser, LUNA_TOKEN_RIGHT_PAREN)) {
        do {
            LunaExpression *argument = luna_parser_parse_expression(parser);
            if (argument == NULL) {
                luna_parser_leave_nesting(parser);
                return call;
            }

            *next_argument = argument;
            next_argument = &argument->next;
            call->as.call.argument_count += 1U;
        } while (luna_parser_match(parser, LUNA_TOKEN_COMMA));
    }

    if (!luna_parser_expect(parser, LUNA_TOKEN_RIGHT_PAREN,
                            "after function arguments")) {
        luna_parser_leave_nesting(parser);
        return call;
    }

    luna_parser_leave_nesting(parser);
    call->span = luna_parser_join_spans(name_token.span, parser->previous.span);
    return call;
}

static LunaExpression *luna_parser_parse_primary(LunaParser *parser) {
    const LunaToken token = parser->current;

    if (luna_parser_match(parser, LUNA_TOKEN_INTEGER)) {
        LunaExpression *expression = luna_parser_new_expression(
            parser, LUNA_EXPRESSION_INTEGER, token.span);
        if (expression != NULL) {
            uint64_t value = 0U;
            (void)luna_parser_parse_integer(parser, token, &value);
            expression->as.integer = value;
        }
        return expression;
    }

    if (luna_parser_match(parser, LUNA_TOKEN_FLOAT)) {
        LunaExpression *expression = luna_parser_new_expression(
            parser, LUNA_EXPRESSION_FLOAT, token.span);
        if (expression != NULL) {
            (void)luna_parser_validate_float(parser, token);
            expression->as.floating = luna_parser_token_text(token);
        }
        return expression;
    }

    if (luna_parser_match(parser, LUNA_TOKEN_TRUE) ||
        luna_parser_match(parser, LUNA_TOKEN_FALSE)) {
        LunaExpression *expression = luna_parser_new_expression(
            parser, LUNA_EXPRESSION_BOOLEAN, token.span);
        if (expression != NULL) {
            expression->as.boolean = token.kind == LUNA_TOKEN_TRUE;
        }
        return expression;
    }

    if (luna_parser_match(parser, LUNA_TOKEN_IDENTIFIER)) {
        if (luna_parser_match(parser, LUNA_TOKEN_LEFT_PAREN)) {
            return luna_parser_parse_call(parser, token);
        }

        LunaExpression *expression = luna_parser_new_expression(
            parser, LUNA_EXPRESSION_NAME, token.span);
        if (expression != NULL) {
            expression->as.name = luna_parser_token_text(token);
        }
        return expression;
    }

    if (luna_parser_match(parser, LUNA_TOKEN_LEFT_PAREN)) {
        if (!luna_parser_enter_nesting(parser, token.span)) {
            return NULL;
        }
        LunaExpression *expression = luna_parser_parse_expression(parser);
        luna_parser_leave_nesting(parser);
        (void)luna_parser_expect(parser, LUNA_TOKEN_RIGHT_PAREN,
                                 "after expression");
        return expression;
    }

    luna_diagnostic_error(parser->diagnostics, token.span,
                          "expected an expression, found %s",
                          luna_token_kind_name(token.kind));

    if (!luna_parser_check(parser, LUNA_TOKEN_END)) {
        luna_parser_advance(parser);
    }

    return NULL;
}

static bool luna_parser_is_unary_operator(LunaTokenKind kind) {
    return kind == LUNA_TOKEN_PLUS || kind == LUNA_TOKEN_MINUS ||
           kind == LUNA_TOKEN_BANG || kind == LUNA_TOKEN_TILDE;
}

static LunaExpression *luna_parser_parse_unary(LunaParser *parser) {
    if (!luna_parser_is_unary_operator(parser->current.kind)) {
        return luna_parser_parse_primary(parser);
    }

    const LunaToken operator_token = parser->current;
    if (!luna_parser_enter_nesting(parser, operator_token.span)) {
        return NULL;
    }
    luna_parser_advance(parser);
    LunaExpression *operand = luna_parser_parse_unary(parser);
    luna_parser_leave_nesting(parser);
    if (operand == NULL) {
        return NULL;
    }

    LunaExpression *expression = luna_parser_new_expression(
        parser, LUNA_EXPRESSION_UNARY,
        luna_parser_join_spans(operator_token.span, operand->span));
    if (expression != NULL) {
        expression->as.unary.operator_kind = operator_token.kind;
        expression->as.unary.operand = operand;
    }
    return expression;
}

static LunaExpression *luna_parser_parse_cast(LunaParser *parser) {
    LunaExpression *expression = luna_parser_parse_unary(parser);
    while (expression != NULL && luna_parser_match(parser, LUNA_TOKEN_AS)) {
        const LunaTypeRef target_type = luna_parser_parse_type(parser);
        LunaExpression *cast = luna_parser_new_expression(
            parser, LUNA_EXPRESSION_CAST,
            luna_parser_join_spans(expression->span, target_type.span));
        if (cast == NULL) {
            return expression;
        }
        cast->as.cast.operand = expression;
        cast->as.cast.target_type = target_type;
        expression = cast;
    }
    return expression;
}

static int luna_parser_binary_precedence(LunaTokenKind kind) {
    switch (kind) {
    case LUNA_TOKEN_LOGICAL_OR:
        return 1;
    case LUNA_TOKEN_LOGICAL_AND:
        return 2;
    case LUNA_TOKEN_PIPE:
        return 3;
    case LUNA_TOKEN_CARET:
        return 4;
    case LUNA_TOKEN_AMPERSAND:
        return 5;
    case LUNA_TOKEN_EQUAL_EQUAL:
    case LUNA_TOKEN_BANG_EQUAL:
        return 6;
    case LUNA_TOKEN_LESS:
    case LUNA_TOKEN_LESS_EQUAL:
    case LUNA_TOKEN_GREATER:
    case LUNA_TOKEN_GREATER_EQUAL:
        return 7;
    case LUNA_TOKEN_SHIFT_LEFT:
    case LUNA_TOKEN_SHIFT_RIGHT:
        return 8;
    case LUNA_TOKEN_PLUS:
    case LUNA_TOKEN_MINUS:
        return 9;
    case LUNA_TOKEN_STAR:
    case LUNA_TOKEN_SLASH:
    case LUNA_TOKEN_PERCENT:
        return 10;
    default:
        return 0;
    }
}

static LunaExpression *luna_parser_parse_binary(LunaParser *parser,
                                                int minimum_precedence) {
    LunaExpression *left = luna_parser_parse_cast(parser);
    if (left == NULL) {
        return NULL;
    }

    for (;;) {
        const int precedence =
            luna_parser_binary_precedence(parser->current.kind);
        if (precedence < minimum_precedence) {
            break;
        }

        const LunaToken operator_token = parser->current;
        luna_parser_advance(parser);

        LunaExpression *right =
            luna_parser_parse_binary(parser, precedence + 1);
        if (right == NULL) {
            return left;
        }

        LunaExpression *expression = luna_parser_new_expression(
            parser, LUNA_EXPRESSION_BINARY,
            luna_parser_join_spans(left->span, right->span));
        if (expression == NULL) {
            return left;
        }

        expression->as.binary.operator_kind = operator_token.kind;
        expression->as.binary.left = left;
        expression->as.binary.right = right;
        left = expression;
    }

    return left;
}

static LunaExpression *luna_parser_parse_expression(LunaParser *parser) {
    return luna_parser_parse_binary(parser, 1);
}

static LunaBlock *luna_parser_parse_block(LunaParser *parser);

static LunaStatement *luna_parser_new_statement(LunaParser *parser,
                                                LunaStatementKind kind,
                                                LunaSourceSpan span) {
    LunaStatement *statement = luna_parser_allocate(
        parser, sizeof(LunaStatement), _Alignof(LunaStatement));
    if (statement != NULL) {
        statement->kind = kind;
        statement->span = span;
    }
    return statement;
}

static LunaStatement *luna_parser_wrap_block(LunaParser *parser,
                                             LunaBlock *block) {
    if (block == NULL) {
        return NULL;
    }

    LunaStatement *statement =
        luna_parser_new_statement(parser, LUNA_STATEMENT_BLOCK, block->span);
    if (statement != NULL) {
        statement->as.block = *block;
    }
    return statement;
}

static LunaStatement *luna_parser_parse_if_statement(LunaParser *parser) {
    const LunaToken if_token = parser->previous;
    if (!luna_parser_enter_nesting(parser, if_token.span)) {
        return NULL;
    }
    (void)luna_parser_expect(parser, LUNA_TOKEN_LEFT_PAREN, "after 'if'");
    LunaExpression *condition = luna_parser_parse_expression(parser);
    (void)luna_parser_expect(parser, LUNA_TOKEN_RIGHT_PAREN,
                             "after if condition");

    LunaBlock *then_block = luna_parser_parse_block(parser);
    LunaStatement *else_branch = NULL;

    if (luna_parser_match(parser, LUNA_TOKEN_ELSE)) {
        if (luna_parser_match(parser, LUNA_TOKEN_IF)) {
            else_branch = luna_parser_parse_if_statement(parser);
        } else {
            else_branch =
                luna_parser_wrap_block(parser, luna_parser_parse_block(parser));
        }
    }

    LunaSourceSpan end_span = if_token.span;
    if (else_branch != NULL) {
        end_span = else_branch->span;
    } else if (then_block != NULL) {
        end_span = then_block->span;
    }

    LunaStatement *statement = luna_parser_new_statement(
        parser, LUNA_STATEMENT_IF,
        luna_parser_join_spans(if_token.span, end_span));
    if (statement != NULL) {
        statement->as.if_statement.condition = condition;
        statement->as.if_statement.then_block = then_block;
        statement->as.if_statement.else_branch = else_branch;
    }
    luna_parser_leave_nesting(parser);
    return statement;
}

static LunaStatement *luna_parser_parse_while_statement(LunaParser *parser) {
    const LunaToken while_token = parser->previous;
    (void)luna_parser_expect(parser, LUNA_TOKEN_LEFT_PAREN, "after 'while'");
    LunaExpression *condition = luna_parser_parse_expression(parser);
    (void)luna_parser_expect(parser, LUNA_TOKEN_RIGHT_PAREN,
                             "after while condition");
    LunaBlock *body = luna_parser_parse_block(parser);

    LunaStatement *statement = luna_parser_new_statement(
        parser, LUNA_STATEMENT_WHILE,
        body == NULL ? while_token.span
                     : luna_parser_join_spans(while_token.span, body->span));
    if (statement != NULL) {
        statement->as.while_statement.condition = condition;
        statement->as.while_statement.body = body;
    }
    return statement;
}

static LunaStatement *
luna_parser_parse_declaration(LunaParser *parser, bool is_mutable,
                              LunaSourceSpan keyword_span) {
    const LunaToken name_token = parser->current;
    if (!luna_parser_expect(parser, LUNA_TOKEN_IDENTIFIER,
                            "as variable name")) {
        return NULL;
    }

    (void)luna_parser_expect(parser, LUNA_TOKEN_COLON, "after variable name");
    const LunaTypeRef type = luna_parser_parse_type(parser);
    (void)luna_parser_expect(parser, LUNA_TOKEN_EQUAL,
                             "before variable initializer");
    LunaExpression *initializer = luna_parser_parse_expression(parser);
    (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON,
                             "after variable declaration");

    LunaStatement *statement = luna_parser_new_statement(
        parser, LUNA_STATEMENT_DECLARATION,
        luna_parser_join_spans(keyword_span, parser->previous.span));
    if (statement != NULL) {
        statement->as.declaration.is_mutable = is_mutable;
        statement->as.declaration.name = luna_parser_token_text(name_token);
        statement->as.declaration.type = type;
        statement->as.declaration.initializer = initializer;
    }
    return statement;
}

static bool luna_parser_is_assignment_operator(LunaTokenKind kind) {
    switch (kind) {
    case LUNA_TOKEN_EQUAL:
    case LUNA_TOKEN_PLUS_EQUAL:
    case LUNA_TOKEN_MINUS_EQUAL:
    case LUNA_TOKEN_STAR_EQUAL:
    case LUNA_TOKEN_SLASH_EQUAL:
    case LUNA_TOKEN_PERCENT_EQUAL:
    case LUNA_TOKEN_AMPERSAND_EQUAL:
    case LUNA_TOKEN_PIPE_EQUAL:
    case LUNA_TOKEN_CARET_EQUAL:
    case LUNA_TOKEN_SHIFT_LEFT_EQUAL:
    case LUNA_TOKEN_SHIFT_RIGHT_EQUAL:
        return true;

    default:
        return false;
    }
}

static LunaStatement *luna_parser_parse_statement(LunaParser *parser) {
    if (luna_parser_check(parser, LUNA_TOKEN_LEFT_BRACE)) {
        return luna_parser_wrap_block(parser, luna_parser_parse_block(parser));
    }

    if (luna_parser_match(parser, LUNA_TOKEN_LET)) {
        return luna_parser_parse_declaration(parser, false,
                                             parser->previous.span);
    }

    if (luna_parser_match(parser, LUNA_TOKEN_VAR)) {
        return luna_parser_parse_declaration(parser, true,
                                             parser->previous.span);
    }

    if (luna_parser_match(parser, LUNA_TOKEN_IF)) {
        return luna_parser_parse_if_statement(parser);
    }

    if (luna_parser_match(parser, LUNA_TOKEN_WHILE)) {
        return luna_parser_parse_while_statement(parser);
    }

    if (luna_parser_match(parser, LUNA_TOKEN_BREAK)) {
        const LunaSourceSpan start = parser->previous.span;
        (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON, "after 'break'");
        return luna_parser_new_statement(
            parser, LUNA_STATEMENT_BREAK,
            luna_parser_join_spans(start, parser->previous.span));
    }

    if (luna_parser_match(parser, LUNA_TOKEN_CONTINUE)) {
        const LunaSourceSpan start = parser->previous.span;
        (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON,
                                 "after 'continue'");
        return luna_parser_new_statement(
            parser, LUNA_STATEMENT_CONTINUE,
            luna_parser_join_spans(start, parser->previous.span));
    }

    if (luna_parser_match(parser, LUNA_TOKEN_RETURN)) {
        const LunaSourceSpan start = parser->previous.span;
        LunaExpression *value = NULL;
        if (!luna_parser_check(parser, LUNA_TOKEN_SEMICOLON)) {
            value = luna_parser_parse_expression(parser);
        }
        (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON,
                                 "after return statement");

        LunaStatement *statement = luna_parser_new_statement(
            parser, LUNA_STATEMENT_RETURN,
            luna_parser_join_spans(start, parser->previous.span));
        if (statement != NULL) {
            statement->as.return_value = value;
        }
        return statement;
    }

    if (luna_parser_check(parser, LUNA_TOKEN_DO) ||
        luna_parser_check(parser, LUNA_TOKEN_FOR) ||
        luna_parser_check(parser, LUNA_TOKEN_SWITCH)) {
        const LunaToken unsupported = parser->current;
        luna_diagnostic_error(
            parser->diagnostics, unsupported.span,
            "%s is accepted by the language design but is not implemented "
            "in the current bootstrap compiler",
            luna_token_kind_name(unsupported.kind));
        luna_parser_advance(parser);
        return NULL;
    }

    LunaExpression *expression = luna_parser_parse_expression(parser);
    if (expression == NULL) {
        return NULL;
    }

    if (luna_parser_is_assignment_operator(parser->current.kind)) {
        const LunaToken operator_token = parser->current;
        luna_parser_advance(parser);
        LunaExpression *value = luna_parser_parse_expression(parser);
        (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON,
                                 "after assignment");

        if (expression->kind != LUNA_EXPRESSION_NAME) {
            luna_diagnostic_error(
                parser->diagnostics, expression->span,
                "bootstrap assignments require a local variable name");
            return NULL;
        }

        LunaStatement *statement = luna_parser_new_statement(
            parser, LUNA_STATEMENT_ASSIGNMENT,
            luna_parser_join_spans(expression->span, parser->previous.span));
        if (statement != NULL) {
            statement->as.assignment.name = expression->as.name;
            statement->as.assignment.operator_kind = operator_token.kind;
            statement->as.assignment.value = value;
        }
        return statement;
    }

    (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON, "after expression");
    LunaStatement *statement = luna_parser_new_statement(
        parser, LUNA_STATEMENT_EXPRESSION,
        luna_parser_join_spans(expression->span, parser->previous.span));
    if (statement != NULL) {
        statement->as.expression = expression;
    }
    return statement;
}

static LunaBlock *luna_parser_parse_block(LunaParser *parser) {
    if (!luna_parser_expect(parser, LUNA_TOKEN_LEFT_BRACE, "to begin block")) {
        return NULL;
    }
    const LunaSourceSpan start_span = parser->previous.span;
    if (!luna_parser_enter_nesting(parser, start_span)) {
        return NULL;
    }

    LunaBlock *block =
        luna_parser_allocate(parser, sizeof(LunaBlock), _Alignof(LunaBlock));
    if (block == NULL) {
        luna_parser_leave_nesting(parser);
        return NULL;
    }

    while (!luna_parser_check(parser, LUNA_TOKEN_RIGHT_BRACE) &&
           !luna_parser_check(parser, LUNA_TOKEN_END)) {
        const size_t offset_before = parser->current.span.offset;
        LunaStatement *statement = luna_parser_parse_statement(parser);
        if (statement != NULL) {
            if (block->first == NULL) {
                block->first = statement;
            } else {
                block->last->next = statement;
            }
            block->last = statement;
        }

        if (parser->current.span.offset == offset_before &&
            !luna_parser_check(parser, LUNA_TOKEN_END)) {
            luna_parser_advance(parser);
        }
    }

    (void)luna_parser_expect(parser, LUNA_TOKEN_RIGHT_BRACE, "to end block");
    block->span = luna_parser_join_spans(start_span, parser->previous.span);
    luna_parser_leave_nesting(parser);
    return block;
}

static LunaParameter *luna_parser_parse_parameters(LunaParser *parser,
                                                   uint32_t *parameter_count) {
    LunaParameter *first = NULL;
    LunaParameter **next = &first;

    if (luna_parser_check(parser, LUNA_TOKEN_RIGHT_PAREN)) {
        return NULL;
    }

    do {
        const LunaToken name_token = parser->current;
        if (!luna_parser_expect(parser, LUNA_TOKEN_IDENTIFIER,
                                "as parameter name")) {
            break;
        }

        (void)luna_parser_expect(parser, LUNA_TOKEN_COLON,
                                 "after parameter name");
        const LunaTypeRef type = luna_parser_parse_type(parser);

        LunaParameter *parameter = luna_parser_allocate(
            parser, sizeof(LunaParameter), _Alignof(LunaParameter));
        if (parameter == NULL) {
            break;
        }

        parameter->name = luna_parser_token_text(name_token);
        parameter->type = type;
        parameter->span = luna_parser_join_spans(name_token.span, type.span);
        *next = parameter;
        next = &parameter->next;
        *parameter_count += 1U;
    } while (luna_parser_match(parser, LUNA_TOKEN_COMMA));

    return first;
}

static LunaFunction *luna_parser_parse_function(LunaParser *parser,
                                                bool is_exported,
                                                LunaSourceSpan start_span) {
    const LunaToken name_token = parser->current;
    if (!luna_parser_expect(parser, LUNA_TOKEN_IDENTIFIER,
                            "as function name")) {
        return NULL;
    }

    (void)luna_parser_expect(parser, LUNA_TOKEN_LEFT_PAREN,
                             "after function name");
    uint32_t parameter_count = 0U;
    LunaParameter *parameters =
        luna_parser_parse_parameters(parser, &parameter_count);
    (void)luna_parser_expect(parser, LUNA_TOKEN_RIGHT_PAREN,
                             "after parameters");

    LunaTypeRef return_type = {
        .kind = LUNA_TYPE_VOID,
        .span = parser->previous.span,
    };
    if (luna_parser_match(parser, LUNA_TOKEN_ARROW)) {
        return_type = luna_parser_parse_type(parser);
    }

    const bool is_declaration = luna_parser_match(parser, LUNA_TOKEN_SEMICOLON);
    LunaBlock *body = NULL;
    if (!is_declaration) {
        body = luna_parser_parse_block(parser);
    }

    LunaFunction *function = luna_parser_allocate(parser, sizeof(LunaFunction),
                                                  _Alignof(LunaFunction));
    if (function == NULL) {
        return NULL;
    }

    function->name = luna_parser_token_text(name_token);
    LunaSourceSpan end_span = parser->previous.span;
    if (!is_declaration && body != NULL) {
        end_span = body->span;
    }
    function->span = luna_parser_join_spans(start_span, end_span);
    function->is_exported = is_exported;
    function->is_declaration = is_declaration;
    function->first_parameter = parameters;
    function->parameter_count = parameter_count;
    function->return_type = return_type;
    function->body = body;
    return function;
}

static bool luna_parser_parse_module_name(LunaParser *parser,
                                          LunaStringView *name,
                                          LunaSourceSpan *span) {
    const LunaToken first = parser->current;
    if (!luna_parser_expect(parser, LUNA_TOKEN_IDENTIFIER, "as module name")) {
        return false;
    }

    LunaToken last = first;
    while (luna_parser_match(parser, LUNA_TOKEN_DOT)) {
        last = parser->current;
        if (!luna_parser_expect(parser, LUNA_TOKEN_IDENTIFIER,
                                "after '.' in module name")) {
            return false;
        }
    }

    *span = luna_parser_join_spans(first.span, last.span);
    *name = luna_source_span_text(*span);
    return true;
}

void luna_parser_init(LunaParser *parser, const LunaSourceFile *source,
                      LunaDiagnosticEngine *diagnostics, LunaArena *arena) {
    luna_lexer_init(&parser->lexer, source, diagnostics);
    parser->diagnostics = diagnostics;
    parser->arena = arena;
    parser->current = (LunaToken){0};
    parser->previous = (LunaToken){0};
    parser->nesting_depth = 0U;
    luna_parser_advance(parser);
}

LunaProgram *luna_parser_parse_program(LunaParser *parser) {
    LunaProgram *program = luna_parser_allocate(parser, sizeof(LunaProgram),
                                                _Alignof(LunaProgram));
    if (program == NULL) {
        return NULL;
    }
    program->source = parser->lexer.source;

    program->is_interface = luna_parser_match(parser, LUNA_TOKEN_EXPORT);
    if (!luna_parser_expect(parser, LUNA_TOKEN_MODULE,
                            "at the start of a source unit")) {
        return program;
    }

    if (!luna_parser_parse_module_name(parser, &program->module_name,
                                       &program->module_span)) {
        return program;
    }

    (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON,
                             "after module declaration");

    LunaImport **next_import = &program->first_import;
    while (luna_parser_match(parser, LUNA_TOKEN_IMPORT)) {
        const LunaSourceSpan import_start = parser->previous.span;
        LunaImport *import = luna_parser_allocate(parser, sizeof(LunaImport),
                                                  _Alignof(LunaImport));
        if (import == NULL) {
            return program;
        }

        if (!luna_parser_parse_module_name(parser, &import->module_name,
                                           &import->span)) {
            return program;
        }
        import->span = luna_parser_join_spans(import_start, import->span);
        (void)luna_parser_expect(parser, LUNA_TOKEN_SEMICOLON, "after import");

        *next_import = import;
        next_import = &import->next;
    }

    LunaFunction **next_function = &program->first_function;
    while (!luna_parser_check(parser, LUNA_TOKEN_END)) {
        const bool is_exported = luna_parser_match(parser, LUNA_TOKEN_EXPORT);
        const LunaSourceSpan start_span = parser->current.span;

        if (!luna_parser_match(parser, LUNA_TOKEN_FN)) {
            luna_diagnostic_error(
                parser->diagnostics, parser->current.span,
                "the bootstrap compiler expects a function declaration, "
                "found %s",
                luna_token_kind_name(parser->current.kind));
            luna_parser_advance(parser);
            continue;
        }

        LunaFunction *function =
            luna_parser_parse_function(parser, is_exported, start_span);
        if (function != NULL) {
            *next_function = function;
            next_function = &function->next;
        }
    }

    return program;
}

#include "luna/frontend/source/source.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *luna_copy_c_string(const char *text) {
    if (text == NULL) {
        return NULL;
    }

    const size_t length = strlen(text);
    if (length == SIZE_MAX) {
        return NULL;
    }

    char *copy = malloc(length + 1U);
    if (copy == NULL) {
        return NULL;
    }

    memcpy(copy, text, length + 1U);
    return copy;
}

bool luna_source_load(const char *path, LunaSourceFile *source) {
    if (source == NULL) {
        return false;
    }
    *source = (LunaSourceFile){0};

    if (path == NULL) {
        return false;
    }

    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        return false;
    }

    size_t length = 0U;
    size_t capacity = 4096U;
    char *text = malloc(capacity + 1U);
    if (text == NULL) {
        (void)fclose(file);
        return false;
    }

    bool success = true;
    while (!feof(file)) {
        if (length == capacity) {
            if (capacity > (SIZE_MAX - 1U) / 2U) {
                success = false;
                break;
            }

            capacity *= 2U;
            char *new_text = realloc(text, capacity + 1U);
            if (new_text == NULL) {
                success = false;
                break;
            }
            text = new_text;
        }

        const size_t read_count =
            fread(text + length, 1U, capacity - length, file);
        length += read_count;

        if (ferror(file) != 0) {
            success = false;
            break;
        }
    }

    if (fclose(file) != 0) {
        success = false;
    }

    char *path_copy = NULL;
    if (success) {
        path_copy = luna_copy_c_string(path);
        success = path_copy != NULL;
    }

    if (!success) {
        free(text);
        free(path_copy);
        return false;
    }

    text[length] = '\0';
    source->path = path_copy;
    source->text = text;
    source->length = length;
    return true;
}

bool luna_source_from_memory(const char *path, const char *text,
                             LunaSourceFile *source) {
    if (text == NULL) {
        return false;
    }
    return luna_source_from_bytes(path, text, strlen(text), source);
}

bool luna_source_from_bytes(const char *path, const char *text, size_t length,
                            LunaSourceFile *source) {
    if (source == NULL) {
        return false;
    }
    *source = (LunaSourceFile){0};

    if (path == NULL || text == NULL || length == SIZE_MAX) {
        return false;
    }

    source->path = luna_copy_c_string(path);
    source->text = malloc(length + 1U);
    if (source->path == NULL || source->text == NULL) {
        luna_source_destroy(source);
        return false;
    }

    if (length > 0U) {
        memcpy(source->text, text, length);
    }
    source->text[length] = '\0';
    source->length = length;
    return true;
}

void luna_source_destroy(LunaSourceFile *source) {
    if (source == NULL) {
        return;
    }

    free(source->path);
    free(source->text);
    *source = (LunaSourceFile){0};
}

LunaStringView luna_source_span_text(LunaSourceSpan span) {
    if (span.source == NULL || span.offset > span.source->length ||
        span.length > span.source->length - span.offset) {
        return luna_string_view(NULL, 0U);
    }

    return luna_string_view(span.source->text + span.offset, span.length);
}

#include "luna/frontend/support/arena.h"

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct LunaArenaBlock {
    LunaArenaBlock *next;
    size_t capacity;
    size_t used;
    max_align_t alignment;
    unsigned char data[];
};

static bool luna_is_power_of_two(size_t value) {
    return value != 0U && (value & (value - 1U)) == 0U;
}

static bool luna_align_up(size_t value, size_t alignment, size_t *result) {
    const size_t mask = alignment - 1U;

    if (value > SIZE_MAX - mask) {
        return false;
    }

    *result = (value + mask) & ~mask;
    return true;
}

static LunaArenaBlock *luna_arena_new_block(size_t capacity) {
    if (capacity > SIZE_MAX - sizeof(LunaArenaBlock)) {
        return NULL;
    }

    LunaArenaBlock *block = malloc(sizeof(LunaArenaBlock) + capacity);
    if (block == NULL) {
        return NULL;
    }

    block->next = NULL;
    block->capacity = capacity;
    block->used = 0U;
    return block;
}

void luna_arena_init(LunaArena *arena, size_t default_block_size) {
    arena->first = NULL;
    arena->default_block_size =
        default_block_size == 0U ? 16U * 1024U : default_block_size;
}

void luna_arena_destroy(LunaArena *arena) {
    LunaArenaBlock *block = arena->first;

    while (block != NULL) {
        LunaArenaBlock *next = block->next;
        free(block);
        block = next;
    }

    arena->first = NULL;
}

void *luna_arena_allocate(LunaArena *arena, size_t size, size_t alignment) {
    if (!luna_is_power_of_two(alignment) || alignment > _Alignof(max_align_t)) {
        return NULL;
    }

    const size_t allocation_size = size == 0U ? 1U : size;
    LunaArenaBlock *block = arena->first;
    size_t aligned_used = 0U;

    if (block == NULL ||
        !luna_align_up(block->used, alignment, &aligned_used) ||
        aligned_used > block->capacity ||
        allocation_size > block->capacity - aligned_used) {
        size_t capacity = arena->default_block_size;
        if (capacity < allocation_size) {
            capacity = allocation_size;
        }

        if (capacity <= SIZE_MAX - alignment) {
            capacity += alignment;
        }

        LunaArenaBlock *new_block = luna_arena_new_block(capacity);
        if (new_block == NULL) {
            return NULL;
        }

        new_block->next = block;
        arena->first = new_block;
        block = new_block;

        if (!luna_align_up(block->used, alignment, &aligned_used)) {
            return NULL;
        }
    }

    void *allocation = block->data + aligned_used;
    block->used = aligned_used + allocation_size;
    return allocation;
}

void *luna_arena_allocate_zero(LunaArena *arena, size_t size,
                               size_t alignment) {
    void *allocation = luna_arena_allocate(arena, size, alignment);
    if (allocation != NULL) {
        memset(allocation, 0, size);
    }

    return allocation;
}

char *luna_arena_copy_string(LunaArena *arena, LunaStringView value) {
    if (value.length == SIZE_MAX) {
        return NULL;
    }

    char *copy = luna_arena_allocate(arena, value.length + 1U, _Alignof(char));
    if (copy == NULL) {
        return NULL;
    }

    if (value.length > 0U) {
        memcpy(copy, value.data, value.length);
    }
    copy[value.length] = '\0';
    return copy;
}

#include "luna/frontend/support/buffer.h"

#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static bool luna_multiply_size(size_t left, size_t right, size_t *result) {
    if (left != 0U && right > SIZE_MAX / left) {
        return false;
    }

    *result = left * right;
    return true;
}

void luna_vector_init(LunaVector *vector, size_t element_size) {
    vector->data = NULL;
    vector->length = 0U;
    vector->capacity = 0U;
    vector->element_size = element_size;
}

void luna_vector_destroy(LunaVector *vector) {
    free(vector->data);
    vector->data = NULL;
    vector->length = 0U;
    vector->capacity = 0U;
}

bool luna_vector_reserve(LunaVector *vector, size_t capacity) {
    if (capacity <= vector->capacity) {
        return true;
    }

    size_t byte_count = 0U;
    if (vector->element_size == 0U ||
        !luna_multiply_size(capacity, vector->element_size, &byte_count)) {
        return false;
    }

    void *new_data = realloc(vector->data, byte_count);
    if (new_data == NULL) {
        return false;
    }

    vector->data = new_data;
    vector->capacity = capacity;
    return true;
}

bool luna_vector_push(LunaVector *vector, const void *element) {
    if (vector->length == vector->capacity) {
        size_t new_capacity =
            vector->capacity == 0U ? 8U : vector->capacity * 2U;

        if (new_capacity < vector->capacity ||
            !luna_vector_reserve(vector, new_capacity)) {
            return false;
        }
    }

    unsigned char *destination =
        vector->data + (vector->length * vector->element_size);
    memcpy(destination, element, vector->element_size);
    vector->length += 1U;
    return true;
}

void *luna_vector_at(LunaVector *vector, size_t index) {
    if (index >= vector->length) {
        return NULL;
    }

    return vector->data + (index * vector->element_size);
}

const void *luna_vector_at_const(const LunaVector *vector, size_t index) {
    if (index >= vector->length) {
        return NULL;
    }

    return vector->data + (index * vector->element_size);
}

static bool luna_string_builder_reserve(LunaStringBuilder *builder,
                                        size_t required) {
    if (required <= builder->capacity) {
        return true;
    }

    size_t capacity = builder->capacity == 0U ? 128U : builder->capacity;
    while (capacity < required) {
        if (capacity > SIZE_MAX / 2U) {
            capacity = required;
            break;
        }
        capacity *= 2U;
    }

    char *new_data = realloc(builder->data, capacity);
    if (new_data == NULL) {
        return false;
    }

    builder->data = new_data;
    builder->capacity = capacity;
    return true;
}

void luna_string_builder_init(LunaStringBuilder *builder) {
    builder->data = NULL;
    builder->length = 0U;
    builder->capacity = 0U;
}

void luna_string_builder_destroy(LunaStringBuilder *builder) {
    free(builder->data);
    builder->data = NULL;
    builder->length = 0U;
    builder->capacity = 0U;
}

bool luna_string_builder_append(LunaStringBuilder *builder, const char *data,
                                size_t length) {
    if (length > SIZE_MAX - builder->length - 1U) {
        return false;
    }

    const size_t required = builder->length + length + 1U;
    if (!luna_string_builder_reserve(builder, required)) {
        return false;
    }

    if (length > 0U) {
        memcpy(builder->data + builder->length, data, length);
    }
    builder->length += length;
    builder->data[builder->length] = '\0';
    return true;
}

bool luna_string_builder_append_c_string(LunaStringBuilder *builder,
                                         const char *text) {
    return luna_string_builder_append(builder, text, strlen(text));
}

bool luna_string_builder_append_view(LunaStringBuilder *builder,
                                     LunaStringView view) {
    return luna_string_builder_append(builder, view.data, view.length);
}

bool luna_string_builder_append_format(LunaStringBuilder *builder,
                                       const char *format, ...) {
    va_list arguments;
    va_start(arguments, format);

    va_list arguments_copy;
    va_copy(arguments_copy, arguments);
    const int required_count = vsnprintf(NULL, 0U, format, arguments_copy);
    va_end(arguments_copy);

    if (required_count < 0) {
        va_end(arguments);
        return false;
    }

    const size_t required_length = (size_t)required_count;
    if (required_length > SIZE_MAX - builder->length - 1U) {
        va_end(arguments);
        return false;
    }

    const size_t required_capacity = builder->length + required_length + 1U;
    if (!luna_string_builder_reserve(builder, required_capacity)) {
        va_end(arguments);
        return false;
    }

    const int written = vsnprintf(builder->data + builder->length,
                                  required_length + 1U, format, arguments);
    va_end(arguments);

    if (written != required_count) {
        return false;
    }

    builder->length += required_length;
    return true;
}

const char *luna_string_builder_data(const LunaStringBuilder *builder) {
    return builder->data == NULL ? "" : builder->data;
}

#include "luna/frontend/support/string_view.h"

#include <string.h>

LunaStringView luna_string_view(const char *data, size_t length) {
    return (LunaStringView){
        .data = data,
        .length = length,
    };
}

LunaStringView luna_string_view_from_c_string(const char *text) {
    return luna_string_view(text, strlen(text));
}

bool luna_string_view_equal(LunaStringView left, LunaStringView right) {
    if (left.length != right.length) {
        return false;
    }

    if (left.length == 0U) {
        return true;
    }

    return memcmp(left.data, right.data, left.length) == 0;
}

bool luna_string_view_equal_c_string(LunaStringView view, const char *text) {
    return luna_string_view_equal(view, luna_string_view_from_c_string(text));
}

