static uint64_t luna_ir_integer_bit_mask(LunaIrType type,
                                         const LunaDataLayout *data_layout) {
    const uint32_t width = luna_ir_type_bit_width(type, data_layout);
    if (width == 64U) {
        return UINT64_MAX;
    }
    if (width == 0U) {
        return 0U;
    }
    return (UINT64_C(1) << width) - 1U;
}

static bool luna_ir_reject(const char **reason, const char *message) {
    *reason = message;
    return false;
}

static bool luna_ir_verify_value(const LunaIrFunction *function,
                                 LunaIrValueId value, LunaIrType expected_type,
                                 const bool *defined_in_block,
                                 const char **reason) {
    if (value == LUNA_IR_INVALID_ID ||
        (size_t)value >= function->value_types.length) {
        return luna_ir_reject(reason, "value id is out of range");
    }

    if (!defined_in_block[value]) {
        return luna_ir_reject(
            reason, "value is used before its definition or across blocks");
    }

    const LunaIrType *actual_type =
        luna_vector_at_const(&function->value_types, (size_t)value);
    if (*actual_type != expected_type) {
        return luna_ir_reject(reason, "operand type does not match opcode");
    }
    return true;
}

static bool luna_ir_verify_result(const LunaIrFunction *function,
                                  const LunaIrInstruction *instruction,
                                  LunaIrType expected_type,
                                  const char **reason) {
    if (instruction->type != expected_type) {
        return luna_ir_reject(reason,
                              "instruction result type does not match opcode");
    }

    if (expected_type == LUNA_IR_TYPE_VOID) {
        if (instruction->result != LUNA_IR_INVALID_ID) {
            return luna_ir_reject(reason,
                                  "void instruction unexpectedly has a result");
        }
        return true;
    }

    if (instruction->result == LUNA_IR_INVALID_ID ||
        (size_t)instruction->result >= function->value_types.length) {
        return luna_ir_reject(reason, "result value id is out of range");
    }

    const LunaIrType *result_type = luna_vector_at_const(
        &function->value_types, (size_t)instruction->result);
    if (*result_type != expected_type) {
        return luna_ir_reject(reason,
                              "result value type does not match instruction");
    }
    return true;
}

static bool luna_ir_verify_binary(const LunaIrFunction *function,
                                  const LunaIrInstruction *instruction,
                                  const bool *defined_in_block,
                                  LunaIrType operand_type,
                                  LunaIrType result_type, const char **reason) {
    return luna_ir_verify_value(function, instruction->left, operand_type,
                                defined_in_block, reason) &&
           luna_ir_verify_value(function, instruction->right, operand_type,
                                defined_in_block, reason) &&
           luna_ir_verify_result(function, instruction, result_type, reason);
}

static bool luna_ir_verify_call(const LunaIrModule *module,
                                const LunaIrFunction *function,
                                const LunaIrInstruction *instruction,
                                const bool *defined_in_block,
                                bool *argument_used, const char **reason) {
    if ((size_t)instruction->callee >= module->functions.length) {
        return luna_ir_reject(reason, "callee id is out of range");
    }

    const LunaIrFunction *callee =
        luna_ir_module_function_const(module, instruction->callee);
    if ((size_t)instruction->argument_count != callee->parameter_types.length) {
        return luna_ir_reject(reason,
                              "call argument count does not match callee");
    }

    const size_t first_argument = (size_t)instruction->first_argument;
    const size_t argument_count = (size_t)instruction->argument_count;
    if (first_argument > function->arguments.length ||
        argument_count > function->arguments.length - first_argument) {
        return luna_ir_reject(reason, "call argument range is out of bounds");
    }

    if (!luna_ir_verify_result(function, instruction, callee->return_type,
                               reason)) {
        return false;
    }

    for (size_t index = 0U; index < argument_count; index += 1U) {
        const size_t argument_index = first_argument + index;
        if (argument_used[argument_index]) {
            return luna_ir_reject(
                reason, "call argument storage overlaps another call");
        }

        const LunaIrValueId *argument =
            luna_vector_at_const(&function->arguments, argument_index);
        const LunaIrType *parameter_type =
            luna_vector_at_const(&callee->parameter_types, index);
        if (!luna_ir_verify_value(function, *argument, *parameter_type,
                                  defined_in_block, reason)) {
            return false;
        }
        argument_used[argument_index] = true;
    }
    return true;
}

static bool luna_ir_verify_instruction(const LunaIrModule *module,
                                       const LunaIrFunction *function,
                                       const LunaIrInstruction *instruction,
                                       const bool *defined_in_block,
                                       bool *argument_used,
                                       const char **reason) {
    switch (instruction->opcode) {
    case LUNA_IR_CONST_INTEGER:
        if (!luna_ir_type_is_integer(instruction->type)) {
            return luna_ir_reject(reason,
                                  "integer constant has non-integer type");
        }
        if (instruction->immediate >
            luna_ir_integer_bit_mask(instruction->type,
                                     &module->target->data_layout)) {
            return luna_ir_reject(
                reason, "integer constant exceeds its type storage width");
        }
        return luna_ir_verify_result(function, instruction, instruction->type,
                                     reason);

    case LUNA_IR_CONST_FLOAT:
        if (!luna_ir_type_is_float(instruction->type)) {
            return luna_ir_reject(reason,
                                  "floating constant has non-floating type");
        }
        if (instruction->type == LUNA_IR_TYPE_F32 &&
            instruction->immediate > UINT32_MAX) {
            return luna_ir_reject(
                reason, "f32 constant exceeds its type storage width");
        }
        return luna_ir_verify_result(function, instruction, instruction->type,
                                     reason);

    case LUNA_IR_CONST_BOOL:
        if (instruction->immediate != 0U && instruction->immediate != 1U) {
            return luna_ir_reject(reason,
                                  "bool constant must be exactly zero or one");
        }
        return luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_BOOL,
                                     reason);

    case LUNA_IR_LOAD: {
        if ((size_t)instruction->slot >= function->slot_types.length) {
            return luna_ir_reject(reason, "load slot id is out of range");
        }
        const LunaIrType *slot_type = luna_vector_at_const(
            &function->slot_types, (size_t)instruction->slot);
        return luna_ir_verify_result(function, instruction, *slot_type, reason);
    }

    case LUNA_IR_STORE: {
        if ((size_t)instruction->slot >= function->slot_types.length) {
            return luna_ir_reject(reason, "store slot id is out of range");
        }
        const LunaIrType *slot_type = luna_vector_at_const(
            &function->slot_types, (size_t)instruction->slot);
        return luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_VOID,
                                     reason) &&
               luna_ir_verify_value(function, instruction->left, *slot_type,
                                    defined_in_block, reason);
    }

    case LUNA_IR_NEG_INTEGER:
    case LUNA_IR_BIT_NOT_INTEGER:
        if (!luna_ir_type_is_integer(instruction->type)) {
            return luna_ir_reject(reason,
                                  "integer unary operation has invalid type");
        }
        return luna_ir_verify_value(function, instruction->left,
                                    instruction->type, defined_in_block,
                                    reason) &&
               luna_ir_verify_result(function, instruction, instruction->type,
                                     reason);

    case LUNA_IR_NEG_FLOAT:
        if (!luna_ir_type_is_float(instruction->type)) {
            return luna_ir_reject(reason,
                                  "floating unary operation has invalid type");
        }
        return luna_ir_verify_value(function, instruction->left,
                                    instruction->type, defined_in_block,
                                    reason) &&
               luna_ir_verify_result(function, instruction, instruction->type,
                                     reason);

    case LUNA_IR_BOOL_NOT:
        return luna_ir_verify_value(function, instruction->left,
                                    LUNA_IR_TYPE_BOOL, defined_in_block,
                                    reason) &&
               luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_BOOL,
                                     reason);

    case LUNA_IR_CONVERT_INTEGER: {
        if (!luna_ir_type_is_integer(instruction->type)) {
            return luna_ir_reject(reason,
                                  "integer conversion has invalid result type");
        }
        if (instruction->left == LUNA_IR_INVALID_ID ||
            (size_t)instruction->left >= function->value_types.length) {
            return luna_ir_reject(reason,
                                  "conversion value id is out of range");
        }
        const LunaIrType *source_type = luna_vector_at_const(
            &function->value_types, (size_t)instruction->left);
        if (!luna_ir_type_is_integer(*source_type)) {
            return luna_ir_reject(reason,
                                  "integer conversion has invalid source type");
        }
        if (*source_type == instruction->type) {
            return luna_ir_reject(reason, "integer conversion is redundant");
        }
        return luna_ir_verify_value(function, instruction->left, *source_type,
                                    defined_in_block, reason) &&
               luna_ir_verify_result(function, instruction, instruction->type,
                                     reason);
    }

    case LUNA_IR_ADD_INTEGER:
    case LUNA_IR_SUB_INTEGER:
    case LUNA_IR_MUL_INTEGER:
    case LUNA_IR_DIV_INTEGER:
    case LUNA_IR_REM_INTEGER:
    case LUNA_IR_BIT_AND_INTEGER:
    case LUNA_IR_BIT_OR_INTEGER:
    case LUNA_IR_BIT_XOR_INTEGER:
    case LUNA_IR_SHIFT_LEFT_INTEGER:
    case LUNA_IR_SHIFT_RIGHT_INTEGER:
        if (!luna_ir_type_is_integer(instruction->type)) {
            return luna_ir_reject(reason,
                                  "integer binary operation has invalid type");
        }
        return luna_ir_verify_binary(function, instruction, defined_in_block,
                                     instruction->type, instruction->type,
                                     reason);

    case LUNA_IR_ADD_FLOAT:
    case LUNA_IR_SUB_FLOAT:
    case LUNA_IR_MUL_FLOAT:
    case LUNA_IR_DIV_FLOAT:
        if (!luna_ir_type_is_float(instruction->type)) {
            return luna_ir_reject(reason,
                                  "floating binary operation has invalid type");
        }
        return luna_ir_verify_binary(function, instruction, defined_in_block,
                                     instruction->type, instruction->type,
                                     reason);

    case LUNA_IR_COMPARE_EQUAL:
    case LUNA_IR_COMPARE_NOT_EQUAL: {
        if (instruction->left == LUNA_IR_INVALID_ID ||
            (size_t)instruction->left >= function->value_types.length) {
            return luna_ir_reject(reason,
                                  "comparison value id is out of range");
        }
        const LunaIrType *operand_type = luna_vector_at_const(
            &function->value_types, (size_t)instruction->left);
        if (!luna_ir_type_is_value(*operand_type)) {
            return luna_ir_reject(reason,
                                  "equality operand type is not comparable");
        }
        return luna_ir_verify_value(function, instruction->left, *operand_type,
                                    defined_in_block, reason) &&
               luna_ir_verify_value(function, instruction->right, *operand_type,
                                    defined_in_block, reason) &&
               luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_BOOL,
                                     reason);
    }

    case LUNA_IR_COMPARE_LESS_INTEGER:
    case LUNA_IR_COMPARE_LESS_EQUAL_INTEGER:
    case LUNA_IR_COMPARE_GREATER_INTEGER:
    case LUNA_IR_COMPARE_GREATER_EQUAL_INTEGER: {
        if (instruction->left == LUNA_IR_INVALID_ID ||
            (size_t)instruction->left >= function->value_types.length) {
            return luna_ir_reject(reason,
                                  "comparison value id is out of range");
        }
        const LunaIrType *operand_type = luna_vector_at_const(
            &function->value_types, (size_t)instruction->left);
        if (!luna_ir_type_is_integer(*operand_type)) {
            return luna_ir_reject(reason,
                                  "ordering operand type is not integer");
        }
        return luna_ir_verify_binary(function, instruction, defined_in_block,
                                     *operand_type, LUNA_IR_TYPE_BOOL, reason);
    }

    case LUNA_IR_COMPARE_LESS_FLOAT:
    case LUNA_IR_COMPARE_LESS_EQUAL_FLOAT:
    case LUNA_IR_COMPARE_GREATER_FLOAT:
    case LUNA_IR_COMPARE_GREATER_EQUAL_FLOAT: {
        if (instruction->left == LUNA_IR_INVALID_ID ||
            (size_t)instruction->left >= function->value_types.length) {
            return luna_ir_reject(reason,
                                  "comparison value id is out of range");
        }
        const LunaIrType *operand_type = luna_vector_at_const(
            &function->value_types, (size_t)instruction->left);
        if (!luna_ir_type_is_float(*operand_type)) {
            return luna_ir_reject(reason,
                                  "floating ordering operand is not floating");
        }
        return luna_ir_verify_binary(function, instruction, defined_in_block,
                                     *operand_type, LUNA_IR_TYPE_BOOL, reason);
    }

    case LUNA_IR_CALL:
        return luna_ir_verify_call(module, function, instruction,
                                   defined_in_block, argument_used, reason);

    case LUNA_IR_JUMP:
        if ((size_t)instruction->true_block >= function->blocks.length) {
            return luna_ir_reject(reason, "jump target is out of range");
        }
        return luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_VOID,
                                     reason);

    case LUNA_IR_BRANCH:
        if ((size_t)instruction->true_block >= function->blocks.length ||
            (size_t)instruction->false_block >= function->blocks.length) {
            return luna_ir_reject(reason, "branch target is out of range");
        }
        return luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_VOID,
                                     reason) &&
               luna_ir_verify_value(function, instruction->left,
                                    LUNA_IR_TYPE_BOOL, defined_in_block,
                                    reason);

    case LUNA_IR_RETURN:
        if (!luna_ir_verify_result(function, instruction, LUNA_IR_TYPE_VOID,
                                   reason)) {
            return false;
        }
        if (function->return_type == LUNA_IR_TYPE_VOID) {
            if (instruction->left != LUNA_IR_INVALID_ID) {
                return luna_ir_reject(
                    reason, "void function returns an unexpected value");
            }
            return true;
        }
        return luna_ir_verify_value(function, instruction->left,
                                    function->return_type, defined_in_block,
                                    reason);
    }

    return luna_ir_reject(reason, "opcode is invalid");
}

static bool luna_ir_add_computed_predecessor(uint32_t *predecessors,
                                             LunaIrBlockId block,
                                             const char **reason) {
    if (predecessors[block] == UINT32_MAX) {
        return luna_ir_reject(reason, "predecessor count overflows");
    }
    predecessors[block] += 1U;
    return true;
}

static bool luna_ir_verify_function(const LunaIrModule *module,
                                    const LunaIrFunction *function,
                                    size_t function_index, FILE *error_stream) {
    bool *globally_defined = NULL;
    bool *defined_in_block = NULL;
    bool *argument_used = NULL;
    uint32_t *computed_predecessors = NULL;
    bool *reachable = NULL;
    LunaIrBlockId *worklist = NULL;
    bool success = false;

    if (!luna_ir_type_is_return(function->return_type)) {
        (void)fprintf(error_stream,
                      "IR verification: function %zu has invalid return type\n",
                      function_index);
        goto cleanup;
    }

    if (function->blocks.length == 0U) {
        (void)fprintf(error_stream,
                      "IR verification: function %zu has no blocks\n",
                      function_index);
        goto cleanup;
    }

    if (function->parameter_types.length > function->slot_types.length) {
        (void)fprintf(
            error_stream,
            "IR verification: function %zu has fewer slots than parameters\n",
            function_index);
        goto cleanup;
    }

    for (size_t index = 0U; index < function->parameter_types.length;
         index += 1U) {
        const LunaIrType *parameter_type =
            luna_vector_at_const(&function->parameter_types, index);
        const LunaIrType *slot_type =
            luna_vector_at_const(&function->slot_types, index);
        if (!luna_ir_type_is_value(*parameter_type) ||
            *slot_type != *parameter_type) {
            (void)fprintf(error_stream,
                          "IR verification: invalid parameter %zu in function "
                          "%zu\n",
                          index, function_index);
            goto cleanup;
        }
    }

    for (size_t index = 0U; index < function->slot_types.length; index += 1U) {
        const LunaIrType *type =
            luna_vector_at_const(&function->slot_types, index);
        if (!luna_ir_type_is_value(*type)) {
            (void)fprintf(error_stream,
                          "IR verification: invalid slot type at %zu in "
                          "function %zu\n",
                          index, function_index);
            goto cleanup;
        }
    }

    for (size_t index = 0U; index < function->value_types.length; index += 1U) {
        const LunaIrType *type =
            luna_vector_at_const(&function->value_types, index);
        if (!luna_ir_type_is_value(*type)) {
            (void)fprintf(error_stream,
                          "IR verification: invalid value type at %zu in "
                          "function %zu\n",
                          index, function_index);
            goto cleanup;
        }
    }

    if (function->value_types.length > 0U) {
        globally_defined =
            calloc(function->value_types.length, sizeof(*globally_defined));
        defined_in_block =
            calloc(function->value_types.length, sizeof(*defined_in_block));
        if (globally_defined == NULL || defined_in_block == NULL) {
            (void)fputs("IR verification: out of memory\n", error_stream);
            goto cleanup;
        }
    }

    if (function->arguments.length > 0U) {
        argument_used =
            calloc(function->arguments.length, sizeof(*argument_used));
        if (argument_used == NULL) {
            (void)fputs("IR verification: out of memory\n", error_stream);
            goto cleanup;
        }
    }

    computed_predecessors =
        calloc(function->blocks.length, sizeof(*computed_predecessors));
    reachable = calloc(function->blocks.length, sizeof(*reachable));
    worklist = calloc(function->blocks.length, sizeof(*worklist));
    if (computed_predecessors == NULL || reachable == NULL ||
        worklist == NULL) {
        (void)fputs("IR verification: out of memory\n", error_stream);
        goto cleanup;
    }

    for (size_t block_index = 0U; block_index < function->blocks.length;
         block_index += 1U) {
        const LunaIrBlock *block =
            luna_vector_at_const(&function->blocks, block_index);
        if (function->value_types.length > 0U) {
            memset(defined_in_block, 0,
                   function->value_types.length * sizeof(*defined_in_block));
        }

        for (size_t instruction_index = 0U;
             instruction_index < block->instructions.length;
             instruction_index += 1U) {
            const LunaIrInstruction *instruction =
                luna_vector_at_const(&block->instructions, instruction_index);
            const char *reason = "unknown instruction error";

            if (!luna_ir_verify_instruction(module, function, instruction,
                                            defined_in_block, argument_used,
                                            &reason)) {
                (void)fprintf(error_stream,
                              "IR verification: invalid instruction %zu in "
                              "function %zu block %zu: %s\n",
                              instruction_index, function_index, block_index,
                              reason);
                goto cleanup;
            }

            if (instruction->result != LUNA_IR_INVALID_ID) {
                if (globally_defined == NULL ||
                    (size_t)instruction->result >=
                        function->value_types.length) {
                    (void)fprintf(error_stream,
                                  "IR verification: result value is invalid "
                                  "in function %zu block %zu\n",
                                  function_index, block_index);
                    goto cleanup;
                }
                if (globally_defined[instruction->result]) {
                    (void)fprintf(
                        error_stream,
                        "IR verification: value %u is defined more than once "
                        "in function %zu\n",
                        instruction->result, function_index);
                    goto cleanup;
                }
                globally_defined[instruction->result] = true;
                defined_in_block[instruction->result] = true;
            }

            if (luna_ir_opcode_is_terminator(instruction->opcode) &&
                instruction_index + 1U != block->instructions.length) {
                (void)fprintf(error_stream,
                              "IR verification: terminator is not last in "
                              "function %zu block %zu\n",
                              function_index, block_index);
                goto cleanup;
            }
        }

        const bool has_terminator =
            block->instructions.length > 0U &&
            luna_ir_opcode_is_terminator(
                ((const LunaIrInstruction *)luna_vector_at_const(
                     &block->instructions, block->instructions.length - 1U))
                    ->opcode);
        if (block->terminated != has_terminator) {
            (void)fprintf(error_stream,
                          "IR verification: cached termination state is wrong "
                          "in function %zu block %zu\n",
                          function_index, block_index);
            goto cleanup;
        }
        if (block->instructions.length > 0U && !has_terminator) {
            (void)fprintf(error_stream,
                          "IR verification: non-empty block has no terminator "
                          "in function %zu block %zu\n",
                          function_index, block_index);
            goto cleanup;
        }

        if (has_terminator) {
            const LunaIrInstruction *terminator = luna_vector_at_const(
                &block->instructions, block->instructions.length - 1U);
            const char *reason = "invalid predecessor";
            if (terminator->opcode == LUNA_IR_JUMP) {
                if (!luna_ir_add_computed_predecessor(computed_predecessors,
                                                      terminator->true_block,
                                                      &reason)) {
                    (void)fprintf(error_stream,
                                  "IR verification: function %zu: %s\n",
                                  function_index, reason);
                    goto cleanup;
                }
            } else if (terminator->opcode == LUNA_IR_BRANCH) {
                if (!luna_ir_add_computed_predecessor(computed_predecessors,
                                                      terminator->true_block,
                                                      &reason) ||
                    !luna_ir_add_computed_predecessor(computed_predecessors,
                                                      terminator->false_block,
                                                      &reason)) {
                    (void)fprintf(error_stream,
                                  "IR verification: function %zu: %s\n",
                                  function_index, reason);
                    goto cleanup;
                }
            }
        }
    }

    for (size_t index = 0U; index < function->value_types.length; index += 1U) {
        if (!globally_defined[index]) {
            (void)fprintf(error_stream,
                          "IR verification: value %zu has no definition in "
                          "function %zu\n",
                          index, function_index);
            goto cleanup;
        }
    }

    for (size_t index = 0U; index < function->arguments.length; index += 1U) {
        if (!argument_used[index]) {
            (void)fprintf(error_stream,
                          "IR verification: call argument %zu is unused in "
                          "function %zu\n",
                          index, function_index);
            goto cleanup;
        }
    }

    for (size_t block_index = 0U; block_index < function->blocks.length;
         block_index += 1U) {
        const LunaIrBlock *block =
            luna_vector_at_const(&function->blocks, block_index);
        if (block->predecessor_count != computed_predecessors[block_index]) {
            (void)fprintf(error_stream,
                          "IR verification: predecessor count mismatch in "
                          "function %zu block %zu\n",
                          function_index, block_index);
            goto cleanup;
        }
    }

    size_t worklist_head = 0U;
    size_t worklist_length = 1U;
    reachable[0] = true;
    worklist[0] = 0U;
    while (worklist_head < worklist_length) {
        const LunaIrBlockId block_id = worklist[worklist_head];
        worklist_head += 1U;
        const LunaIrBlock *block =
            luna_vector_at_const(&function->blocks, (size_t)block_id);
        if (!block->terminated) {
            (void)fprintf(error_stream,
                          "IR verification: reachable block %u in function "
                          "%zu has no terminator\n",
                          block_id, function_index);
            goto cleanup;
        }

        const LunaIrInstruction *terminator = luna_vector_at_const(
            &block->instructions, block->instructions.length - 1U);
        LunaIrBlockId targets[2] = {
            LUNA_IR_INVALID_ID,
            LUNA_IR_INVALID_ID,
        };
        size_t target_count = 0U;
        if (terminator->opcode == LUNA_IR_JUMP) {
            targets[0] = terminator->true_block;
            target_count = 1U;
        } else if (terminator->opcode == LUNA_IR_BRANCH) {
            targets[0] = terminator->true_block;
            targets[1] = terminator->false_block;
            target_count = 2U;
        }

        for (size_t index = 0U; index < target_count; index += 1U) {
            const LunaIrBlockId target = targets[index];
            if (!reachable[target]) {
                if (worklist_length >= function->blocks.length) {
                    (void)fprintf(error_stream,
                                  "IR verification: reachability worklist "
                                  "overflow in function %zu\n",
                                  function_index);
                    goto cleanup;
                }
                reachable[target] = true;
                worklist[worklist_length] = target;
                worklist_length += 1U;
            }
        }
    }

    success = true;

cleanup:
    free(worklist);
    free(reachable);
    free(computed_predecessors);
    free(argument_used);
    free(defined_in_block);
    free(globally_defined);
    return success;
}

bool luna_ir_verify(const LunaIrModule *module, FILE *error_stream) {
    FILE *stream = error_stream == NULL ? stderr : error_stream;
    if (module == NULL) {
        (void)fputs("IR verification: module is null\n", stream);
        return false;
    }

    if (module->target == NULL || module->target->triple == NULL ||
        module->target->triple[0] == '\0' ||
        !luna_data_layout_is_valid(&module->target->data_layout)) {
        (void)fputs(
            "IR verification: target data layout is missing or invalid\n",
            stream);
        return false;
    }

    if (module->entry_function == LUNA_IR_INVALID_ID ||
        (size_t)module->entry_function >= module->functions.length) {
        (void)fputs("IR verification: missing entry function\n", stream);
        return false;
    }

    const LunaIrFunction *entry =
        luna_ir_module_function_const(module, module->entry_function);
    if (entry->return_type != LUNA_IR_TYPE_I32 ||
        entry->parameter_types.length != 0U) {
        (void)fputs(
            "IR verification: entry function must have type fn() -> i32\n",
            stream);
        return false;
    }

    for (size_t function_index = 0U; function_index < module->functions.length;
         function_index += 1U) {
        const LunaIrFunction *function =
            luna_vector_at_const(&module->functions, function_index);
        if (!luna_ir_verify_function(module, function, function_index,
                                     stream)) {
            return false;
        }
    }

    return true;
}

static bool luna_ir_print_value(LunaStringBuilder *output,
                                LunaIrValueId value) {
    return luna_string_builder_append_format(output, "%%%u", value);
}

static int64_t luna_ir_signed_immediate(LunaIrType type, uint64_t bits,
                                        const LunaDataLayout *data_layout) {
    const uint64_t maximum_bits = luna_ir_integer_bit_mask(type, data_layout);
    const uint64_t maximum_positive = maximum_bits >> 1U;
    if (bits <= maximum_positive) {
        return (int64_t)bits;
    }

    const uint64_t magnitude = maximum_bits - bits + 1U;
    if (magnitude == (UINT64_C(1) << 63U)) {
        return INT64_MIN;
    }
    return -(int64_t)magnitude;
}

static LunaIrType
luna_ir_instruction_operand_type(const LunaIrFunction *function,
                                 const LunaIrInstruction *instruction) {
    const LunaIrType *type =
        luna_vector_at_const(&function->value_types, (size_t)instruction->left);
    return type == NULL ? LUNA_IR_TYPE_VOID : *type;
}

static bool luna_ir_print_instruction(const LunaIrModule *module,
                                      const LunaIrFunction *function,
                                      const LunaIrInstruction *instruction,
                                      LunaStringBuilder *output) {
    if (instruction->result != LUNA_IR_INVALID_ID) {
        if (!luna_ir_print_value(output, instruction->result) ||
            !luna_string_builder_append_c_string(output, " = ")) {
            return false;
        }
    }

    switch (instruction->opcode) {
    case LUNA_IR_CONST_INTEGER:
        if (luna_ir_type_is_signed_integer(instruction->type)) {
            return luna_string_builder_append_format(
                output, "const.%s %" PRId64 "\n",
                luna_ir_type_name(instruction->type),
                luna_ir_signed_immediate(instruction->type,
                                         instruction->immediate,
                                         &module->target->data_layout));
        }
        return luna_string_builder_append_format(
            output, "const.%s %" PRIu64 "\n",
            luna_ir_type_name(instruction->type), instruction->immediate);

    case LUNA_IR_CONST_FLOAT:
        if (instruction->type == LUNA_IR_TYPE_F32) {
            return luna_string_builder_append_format(
                output, "const.f32 0x%08" PRIx32 "\n",
                (uint32_t)instruction->immediate);
        }
        return luna_string_builder_append_format(
            output, "const.f64 0x%016" PRIx64 "\n", instruction->immediate);

    case LUNA_IR_CONST_BOOL:
        return luna_string_builder_append_format(
            output, "const.bool %s\n",
            instruction->immediate == 0U ? "false" : "true");

    case LUNA_IR_LOAD:
        return luna_string_builder_append_format(
            output, "load.%s $%u\n", luna_ir_type_name(instruction->type),
            instruction->slot);

    case LUNA_IR_STORE:
        if (!luna_string_builder_append_format(output, "store $%u, ",
                                               instruction->slot) ||
            !luna_ir_print_value(output, instruction->left)) {
            return false;
        }
        return luna_string_builder_append_c_string(output, "\n");

    case LUNA_IR_NEG_INTEGER:
    case LUNA_IR_NEG_FLOAT:
    case LUNA_IR_BIT_NOT_INTEGER:
    case LUNA_IR_BOOL_NOT: {
        if (instruction->opcode == LUNA_IR_BOOL_NOT) {
            if (!luna_string_builder_append_c_string(output, "not.bool ")) {
                return false;
            }
        } else if (!luna_string_builder_append_format(
                       output, "%s.%s ",
                       instruction->opcode == LUNA_IR_NEG_INTEGER ||
                               instruction->opcode == LUNA_IR_NEG_FLOAT
                           ? "neg"
                           : "bit_not",
                       luna_ir_type_name(instruction->type))) {
            return false;
        }
        if (!luna_ir_print_value(output, instruction->left)) {
            return false;
        }
        return luna_string_builder_append_c_string(output, "\n");
    }

    case LUNA_IR_CONVERT_INTEGER: {
        const LunaIrType source_type =
            luna_ir_instruction_operand_type(function, instruction);
        const uint32_t source_width =
            luna_ir_type_bit_width(source_type, &module->target->data_layout);
        const uint32_t target_width = luna_ir_type_bit_width(
            instruction->type, &module->target->data_layout);
        const char *name = "bitcast";
        if (source_width > target_width) {
            name = "trunc";
        } else if (source_width < target_width) {
            name =
                luna_ir_type_is_signed_integer(source_type) ? "sext" : "zext";
        }

        if (!luna_string_builder_append_format(
                output, "%s.%s.%s ", name, luna_ir_type_name(source_type),
                luna_ir_type_name(instruction->type)) ||
            !luna_ir_print_value(output, instruction->left)) {
            return false;
        }
        return luna_string_builder_append_c_string(output, "\n");
    }

    case LUNA_IR_ADD_INTEGER:
    case LUNA_IR_SUB_INTEGER:
    case LUNA_IR_MUL_INTEGER:
    case LUNA_IR_DIV_INTEGER:
    case LUNA_IR_REM_INTEGER:
    case LUNA_IR_BIT_AND_INTEGER:
    case LUNA_IR_BIT_OR_INTEGER:
    case LUNA_IR_BIT_XOR_INTEGER:
    case LUNA_IR_SHIFT_LEFT_INTEGER:
    case LUNA_IR_SHIFT_RIGHT_INTEGER:
    case LUNA_IR_ADD_FLOAT:
    case LUNA_IR_SUB_FLOAT:
    case LUNA_IR_MUL_FLOAT:
    case LUNA_IR_DIV_FLOAT:
    case LUNA_IR_COMPARE_EQUAL:
    case LUNA_IR_COMPARE_NOT_EQUAL:
    case LUNA_IR_COMPARE_LESS_INTEGER:
    case LUNA_IR_COMPARE_LESS_EQUAL_INTEGER:
    case LUNA_IR_COMPARE_GREATER_INTEGER:
    case LUNA_IR_COMPARE_GREATER_EQUAL_INTEGER:
    case LUNA_IR_COMPARE_LESS_FLOAT:
    case LUNA_IR_COMPARE_LESS_EQUAL_FLOAT:
    case LUNA_IR_COMPARE_GREATER_FLOAT:
    case LUNA_IR_COMPARE_GREATER_EQUAL_FLOAT: {
        const char *name = "<invalid>";
        switch (instruction->opcode) {
        case LUNA_IR_ADD_INTEGER:
        case LUNA_IR_ADD_FLOAT:
            name = "add";
            break;
        case LUNA_IR_SUB_INTEGER:
        case LUNA_IR_SUB_FLOAT:
            name = "sub";
            break;
        case LUNA_IR_MUL_INTEGER:
        case LUNA_IR_MUL_FLOAT:
            name = "mul";
            break;
        case LUNA_IR_DIV_INTEGER:
        case LUNA_IR_DIV_FLOAT:
            name = "div";
            break;
        case LUNA_IR_REM_INTEGER:
            name = "rem";
            break;
        case LUNA_IR_BIT_AND_INTEGER:
            name = "and";
            break;
        case LUNA_IR_BIT_OR_INTEGER:
            name = "or";
            break;
        case LUNA_IR_BIT_XOR_INTEGER:
            name = "xor";
            break;
        case LUNA_IR_SHIFT_LEFT_INTEGER:
            name = "shl";
            break;
        case LUNA_IR_SHIFT_RIGHT_INTEGER:
            name = "shr";
            break;
        case LUNA_IR_COMPARE_EQUAL:
            name = "eq";
            break;
        case LUNA_IR_COMPARE_NOT_EQUAL:
            name = "ne";
            break;
        case LUNA_IR_COMPARE_LESS_INTEGER:
        case LUNA_IR_COMPARE_LESS_FLOAT:
            name = "lt";
            break;
        case LUNA_IR_COMPARE_LESS_EQUAL_INTEGER:
        case LUNA_IR_COMPARE_LESS_EQUAL_FLOAT:
            name = "le";
            break;
        case LUNA_IR_COMPARE_GREATER_INTEGER:
        case LUNA_IR_COMPARE_GREATER_FLOAT:
            name = "gt";
            break;
        case LUNA_IR_COMPARE_GREATER_EQUAL_INTEGER:
        case LUNA_IR_COMPARE_GREATER_EQUAL_FLOAT:
            name = "ge";
            break;
        default:
            break;
        }

        const bool has_type_suffix =
            instruction->opcode != LUNA_IR_COMPARE_EQUAL &&
            instruction->opcode != LUNA_IR_COMPARE_NOT_EQUAL;
        const LunaIrType operation_type =
            instruction->type == LUNA_IR_TYPE_BOOL
                ? luna_ir_instruction_operand_type(function, instruction)
                : instruction->type;
        if (!luna_string_builder_append_c_string(output, name) ||
            (has_type_suffix &&
             !luna_string_builder_append_format(
                 output, ".%s", luna_ir_type_name(operation_type))) ||
            !luna_string_builder_append_c_string(output, " ") ||
            !luna_ir_print_value(output, instruction->left) ||
            !luna_string_builder_append_c_string(output, ", ") ||
            !luna_ir_print_value(output, instruction->right)) {
            return false;
        }
        return luna_string_builder_append_c_string(output, "\n");
    }

    case LUNA_IR_CALL: {
        const LunaIrFunction *callee =
            luna_ir_module_function_const(module, instruction->callee);
        if (!luna_string_builder_append_c_string(output, "call @") ||
            !luna_string_builder_append_view(output, callee->name) ||
            !luna_string_builder_append_c_string(output, "(")) {
            return false;
        }

        for (uint32_t index = 0U; index < instruction->argument_count;
             index += 1U) {
            const LunaIrValueId *argument = luna_vector_at_const(
                &function->arguments,
                (size_t)instruction->first_argument + index);
            if ((index > 0U &&
                 !luna_string_builder_append_c_string(output, ", ")) ||
                !luna_ir_print_value(output, *argument)) {
                return false;
            }
        }

        return luna_string_builder_append_c_string(output, ")\n");
    }

    case LUNA_IR_JUMP:
        return luna_string_builder_append_format(output, "jump bb%u\n",
                                                 instruction->true_block);

    case LUNA_IR_BRANCH:
        if (!luna_string_builder_append_c_string(output, "branch ") ||
            !luna_ir_print_value(output, instruction->left)) {
            return false;
        }
        return luna_string_builder_append_format(output, ", bb%u, bb%u\n",
                                                 instruction->true_block,
                                                 instruction->false_block);

    case LUNA_IR_RETURN:
        if (!luna_string_builder_append_c_string(output, "return")) {
            return false;
        }
        if (instruction->left != LUNA_IR_INVALID_ID) {
            if (!luna_string_builder_append_c_string(output, " ") ||
                !luna_ir_print_value(output, instruction->left)) {
                return false;
            }
        }
        return luna_string_builder_append_c_string(output, "\n");
    }

    return false;
}

bool luna_ir_print(const LunaIrModule *module, LunaStringBuilder *output) {
    if (module == NULL || module->target == NULL ||
        module->target->triple == NULL ||
        !luna_string_builder_append_format(
            output, "ir luna.v0\ntarget \"%s\"\n\n", module->target->triple)) {
        return false;
    }

    for (size_t function_index = 0U; function_index < module->functions.length;
         function_index += 1U) {
        const LunaIrFunction *function =
            luna_vector_at_const(&module->functions, function_index);

        if (!luna_string_builder_append_c_string(output, "fn @") ||
            !luna_string_builder_append_view(output, function->name) ||
            !luna_string_builder_append_c_string(output, "(")) {
            return false;
        }

        for (size_t parameter_index = 0U;
             parameter_index < function->parameter_types.length;
             parameter_index += 1U) {
            const LunaIrType *type = luna_vector_at_const(
                &function->parameter_types, parameter_index);
            if ((parameter_index > 0U &&
                 !luna_string_builder_append_c_string(output, ", ")) ||
                !luna_string_builder_append_format(output, "$%zu: %s",
                                                   parameter_index,
                                                   luna_ir_type_name(*type))) {
                return false;
            }
        }

        if (!luna_string_builder_append_format(
                output, ") -> %s {\n",
                luna_ir_type_name(function->return_type))) {
            return false;
        }

        for (size_t block_index = 0U; block_index < function->blocks.length;
             block_index += 1U) {
            const LunaIrBlock *block =
                luna_vector_at_const(&function->blocks, block_index);

            if (!luna_string_builder_append_format(output, "bb%zu:\n",
                                                   block_index)) {
                return false;
            }

            for (size_t instruction_index = 0U;
                 instruction_index < block->instructions.length;
                 instruction_index += 1U) {
                const LunaIrInstruction *instruction = luna_vector_at_const(
                    &block->instructions, instruction_index);
                if (!luna_string_builder_append_c_string(output, "  ") ||
                    !luna_ir_print_instruction(module, function, instruction,
                                               output)) {
                    return false;
                }
            }
        }

        if (!luna_string_builder_append_c_string(output, "}\n\n")) {
            return false;
        }
    }

    return true;
}

#include "luna/middleend/sema/sema.h"

#include "luna/frontend/support/buffer.h"
#include "luna/frontend/support/string_view.h"

#include <float.h>
#include <limits.h>
#include <math.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#if !defined(__STDC_IEC_60559_BFP__)
#error "floating literals require IEC 60559 floating-point arithmetic"
#endif

_Static_assert(FLT_RADIX == 2, "floating literals require a binary host");
_Static_assert(FLT_MANT_DIG == 24 && FLT_MAX_EXP == 128,
               "floating literals require IEEE-754 binary32");
_Static_assert(DBL_MANT_DIG == 53 && DBL_MAX_EXP == 1024,
               "floating literals require IEEE-754 binary64");
_Static_assert(FLT_HAS_SUBNORM == 1 && DBL_HAS_SUBNORM == 1,
               "floating literals require subnormal support");
_Static_assert(sizeof(float) == sizeof(uint32_t),
               "floating literals require 32-bit float");
_Static_assert(sizeof(double) == sizeof(uint64_t),
               "floating literals require 64-bit double");

typedef struct LunaSemaFunction {
    const LunaFunction *syntax;
    LunaIrFunctionId ir_id;
} LunaSemaFunction;

typedef struct LunaSemaLocal {
    LunaStringView name;
    LunaTypeKind type;
    LunaIrSlotId slot;
    uint32_t scope_depth;
    bool is_mutable;
} LunaSemaLocal;

typedef struct LunaSemaLoop {
    LunaIrBlockId continue_block;
    LunaIrBlockId break_block;
} LunaSemaLoop;

typedef struct LunaCheckedValue {
    LunaIrValueId id;
    LunaTypeKind type;
} LunaCheckedValue;

typedef struct LunaSemaContext {
    const LunaProgram *program;
    LunaDiagnosticEngine *diagnostics;
    LunaIrModule *module;
    LunaVector functions;
    LunaVector locals;
    LunaVector loops;
    LunaIrFunction *current_function;
    const LunaFunction *current_syntax_function;
    LunaIrBlockId current_block;
    uint32_t scope_depth;
    bool reachable;
    bool checking_dead_code;
    bool allocation_failed;
} LunaSemaContext;

static LunaIrType luna_sema_ir_type(LunaTypeKind type) {
    switch (type) {
    case LUNA_TYPE_VOID:
        return LUNA_IR_TYPE_VOID;
    case LUNA_TYPE_BOOL:
        return LUNA_IR_TYPE_BOOL;
    case LUNA_TYPE_I8:
        return LUNA_IR_TYPE_I8;
    case LUNA_TYPE_I16:
        return LUNA_IR_TYPE_I16;
    case LUNA_TYPE_I32:
        return LUNA_IR_TYPE_I32;
    case LUNA_TYPE_I64:
        return LUNA_IR_TYPE_I64;
    case LUNA_TYPE_ISIZE:
        return LUNA_IR_TYPE_ISIZE;
    case LUNA_TYPE_U8:
        return LUNA_IR_TYPE_U8;
    case LUNA_TYPE_U16:
        return LUNA_IR_TYPE_U16;
    case LUNA_TYPE_U32:
        return LUNA_IR_TYPE_U32;
    case LUNA_TYPE_U64:
        return LUNA_IR_TYPE_U64;
    case LUNA_TYPE_USIZE:
        return LUNA_IR_TYPE_USIZE;
    case LUNA_TYPE_F32:
        return LUNA_IR_TYPE_F32;
    case LUNA_TYPE_F64:
        return LUNA_IR_TYPE_F64;
    case LUNA_TYPE_INVALID:
        break;
    }

    return LUNA_IR_TYPE_VOID;
}

static void luna_sema_report_allocation_failure(LunaSemaContext *context) {
    if (!context->allocation_failed) {
        luna_diagnostic_error_plain(context->diagnostics,
                                    "out of memory while building typed IR");
        context->allocation_failed = true;
    }
}

static LunaIrInstruction luna_sema_instruction(LunaIrOpcode opcode,
                                               LunaSourceSpan span) {
    return (LunaIrInstruction){
        .opcode = opcode,
        .type = LUNA_IR_TYPE_VOID,
        .result = LUNA_IR_INVALID_ID,
        .left = LUNA_IR_INVALID_ID,
        .right = LUNA_IR_INVALID_ID,
        .slot = LUNA_IR_INVALID_ID,
        .true_block = LUNA_IR_INVALID_ID,
        .false_block = LUNA_IR_INVALID_ID,
        .callee = LUNA_IR_INVALID_ID,
        .first_argument = 0U,
        .argument_count = 0U,
        .immediate = 0U,
        .span = span,
    };
}

static LunaIrBlock *luna_sema_current_block(LunaSemaContext *context) {
    return luna_ir_function_block(context->current_function,
                                  context->current_block);
}

static bool luna_sema_append_instruction(LunaSemaContext *context,
                                         const LunaIrInstruction *instruction) {
    if (!context->reachable ||
        !luna_ir_block_append(luna_sema_current_block(context), instruction)) {
        luna_sema_report_allocation_failure(context);
        return false;
    }
    return true;
}

static LunaIrBlockId luna_sema_add_block(LunaSemaContext *context) {
    const LunaIrBlockId block_id =
        luna_ir_function_add_block(context->current_function);
    if (block_id == LUNA_IR_INVALID_ID) {
        luna_sema_report_allocation_failure(context);
    }
    return block_id;
}

static LunaIrValueId luna_sema_add_value(LunaSemaContext *context,
                                         LunaTypeKind type) {
    const LunaIrValueId value = luna_ir_function_add_value(
        context->current_function, luna_sema_ir_type(type));
    if (value == LUNA_IR_INVALID_ID) {
        luna_sema_report_allocation_failure(context);
    }
    return value;
}

static bool luna_sema_add_predecessor(LunaSemaContext *context,
                                      LunaIrBlockId block_id) {
    LunaIrBlock *block =
        luna_ir_function_block(context->current_function, block_id);
    if (block == NULL || block->predecessor_count == UINT32_MAX) {
        luna_sema_report_allocation_failure(context);
        return false;
    }

    block->predecessor_count += 1U;
    return true;
}

static bool luna_sema_emit_jump(LunaSemaContext *context, LunaIrBlockId target,
                                LunaSourceSpan span) {
    LunaIrInstruction instruction = luna_sema_instruction(LUNA_IR_JUMP, span);
    instruction.true_block = target;

    if (!luna_sema_append_instruction(context, &instruction) ||
        !luna_sema_add_predecessor(context, target)) {
        return false;
    }

    context->reachable = false;
    return true;
}

static bool luna_sema_emit_branch(LunaSemaContext *context,
                                  LunaIrValueId condition,
                                  LunaIrBlockId true_block,
                                  LunaIrBlockId false_block,
                                  LunaSourceSpan span) {
    LunaIrInstruction instruction = luna_sema_instruction(LUNA_IR_BRANCH, span);
    instruction.left = condition;
    instruction.true_block = true_block;
    instruction.false_block = false_block;

    if (!luna_sema_append_instruction(context, &instruction) ||
        !luna_sema_add_predecessor(context, true_block) ||
        !luna_sema_add_predecessor(context, false_block)) {
        return false;
    }

    context->reachable = false;
    return true;
}

static void luna_sema_set_block(LunaSemaContext *context,
                                LunaIrBlockId block_id) {
    context->current_block = block_id;
    const LunaIrBlock *block =
        luna_ir_function_block(context->current_function, block_id);
    context->reachable =
        block_id == 0U || (block != NULL && block->predecessor_count > 0U);
}

static LunaIrValueId
luna_sema_emit_value_instruction(LunaSemaContext *context,
                                 LunaIrInstruction *instruction,
                                 LunaTypeKind type) {
    instruction->type = luna_sema_ir_type(type);
    instruction->result = luna_sema_add_value(context, type);
    if (instruction->result == LUNA_IR_INVALID_ID ||
        !luna_sema_append_instruction(context, instruction)) {
        return LUNA_IR_INVALID_ID;
    }

    return instruction->result;
}

static LunaSemaFunction *luna_sema_find_function(LunaSemaContext *context,
                                                 LunaStringView name) {
    for (size_t index = 0U; index < context->functions.length; index += 1U) {
        LunaSemaFunction *function = luna_vector_at(&context->functions, index);
        if (luna_string_view_equal(function->syntax->name, name)) {
            return function;
        }
    }

    return NULL;
}

static LunaSemaLocal *luna_sema_find_local(LunaSemaContext *context,
                                           LunaStringView name) {
    for (size_t index = context->locals.length; index > 0U; index -= 1U) {
        LunaSemaLocal *local = luna_vector_at(&context->locals, index - 1U);
        if (luna_string_view_equal(local->name, name)) {
            return local;
        }
    }

    return NULL;
}

static LunaSemaLocal *
luna_sema_find_local_in_current_scope(LunaSemaContext *context,
                                      LunaStringView name) {
    for (size_t index = context->locals.length; index > 0U; index -= 1U) {
        LunaSemaLocal *local = luna_vector_at(&context->locals, index - 1U);
        if (local->scope_depth < context->scope_depth) {
            break;
        }
        if (luna_string_view_equal(local->name, name)) {
            return local;
        }
    }

    return NULL;
}

static bool luna_sema_add_local(LunaSemaContext *context, LunaStringView name,
                                LunaTypeKind type, LunaIrSlotId slot,
                                bool is_mutable) {
    const LunaSemaLocal local = {
        .name = name,
        .type = type,
        .slot = slot,
        .scope_depth = context->scope_depth,
        .is_mutable = is_mutable,
    };

    if (!luna_vector_push(&context->locals, &local)) {
        luna_sema_report_allocation_failure(context);
        return false;
    }
    return true;
}

static void luna_sema_enter_scope(LunaSemaContext *context) {
    context->scope_depth += 1U;
}

static void luna_sema_leave_scope(LunaSemaContext *context) {
    while (context->locals.length > 0U) {
        const LunaSemaLocal *local =
            luna_vector_at_const(&context->locals, context->locals.length - 1U);
        if (local->scope_depth < context->scope_depth) {
            break;
        }
        context->locals.length -= 1U;
    }

    context->scope_depth -= 1U;
}

static bool luna_sema_require_type(LunaSemaContext *context,
                                   LunaCheckedValue value,
                                   LunaTypeKind expected, LunaSourceSpan span) {
    if (value.type == expected) {
        return true;
    }

    luna_diagnostic_error(context->diagnostics, span, "expected %s, found %s",
                          luna_type_kind_name(expected),
                          luna_type_kind_name(value.type));
    return false;
}

static LunaCheckedValue luna_sema_invalid_value(void) {
    return (LunaCheckedValue){
        .id = LUNA_IR_INVALID_ID,
        .type = LUNA_TYPE_INVALID,
    };
}

static LunaCheckedValue
luna_sema_lower_expression_expected(LunaSemaContext *context,
                                    const LunaExpression *expression,
                                    LunaTypeKind expected_type);

static bool luna_sema_is_integer_type(LunaTypeKind type) {
    return luna_type_kind_is_integer(type);
}

static bool luna_sema_is_float_type(LunaTypeKind type) {
    return luna_type_kind_is_float(type);
}

static bool luna_sema_is_numeric_type(LunaTypeKind type) {
    return luna_sema_is_integer_type(type) || luna_sema_is_float_type(type);
}

static LunaIrOpcode
luna_sema_binary_integer_opcode(LunaTokenKind operator_kind) {
    switch (operator_kind) {
    case LUNA_TOKEN_PLUS:
    case LUNA_TOKEN_PLUS_EQUAL:
        return LUNA_IR_ADD_INTEGER;
    case LUNA_TOKEN_MINUS:
    case LUNA_TOKEN_MINUS_EQUAL:
        return LUNA_IR_SUB_INTEGER;
    case LUNA_TOKEN_STAR:
    case LUNA_TOKEN_STAR_EQUAL:
        return LUNA_IR_MUL_INTEGER;
    case LUNA_TOKEN_SLASH:
    case LUNA_TOKEN_SLASH_EQUAL:
        return LUNA_IR_DIV_INTEGER;
    case LUNA_TOKEN_PERCENT:
    case LUNA_TOKEN_PERCENT_EQUAL:
        return LUNA_IR_REM_INTEGER;
    case LUNA_TOKEN_AMPERSAND:
    case LUNA_TOKEN_AMPERSAND_EQUAL:
        return LUNA_IR_BIT_AND_INTEGER;
    case LUNA_TOKEN_PIPE:
    case LUNA_TOKEN_PIPE_EQUAL:
        return LUNA_IR_BIT_OR_INTEGER;
    case LUNA_TOKEN_CARET:
    case LUNA_TOKEN_CARET_EQUAL:
        return LUNA_IR_BIT_XOR_INTEGER;
    case LUNA_TOKEN_SHIFT_LEFT:
    case LUNA_TOKEN_SHIFT_LEFT_EQUAL:
        return LUNA_IR_SHIFT_LEFT_INTEGER;
    case LUNA_TOKEN_SHIFT_RIGHT:
    case LUNA_TOKEN_SHIFT_RIGHT_EQUAL:
        return LUNA_IR_SHIFT_RIGHT_INTEGER;
    case LUNA_TOKEN_LESS:
        return LUNA_IR_COMPARE_LESS_INTEGER;
    case LUNA_TOKEN_LESS_EQUAL:
        return LUNA_IR_COMPARE_LESS_EQUAL_INTEGER;
    case LUNA_TOKEN_GREATER:
        return LUNA_IR_COMPARE_GREATER_INTEGER;
    case LUNA_TOKEN_GREATER_EQUAL:
        return LUNA_IR_COMPARE_GREATER_EQUAL_INTEGER;
    default:
        return LUNA_IR_ADD_INTEGER;
    }
}

static bool luna_sema_binary_float_opcode(LunaTokenKind operator_kind,
                                          LunaIrOpcode *opcode) {
    switch (operator_kind) {
    case LUNA_TOKEN_PLUS:
    case LUNA_TOKEN_PLUS_EQUAL:
        *opcode = LUNA_IR_ADD_FLOAT;
        return true;
    case LUNA_TOKEN_MINUS:
    case LUNA_TOKEN_MINUS_EQUAL:
        *opcode = LUNA_IR_SUB_FLOAT;
        return true;
    case LUNA_TOKEN_STAR:
    case LUNA_TOKEN_STAR_EQUAL:
        *opcode = LUNA_IR_MUL_FLOAT;
        return true;
    case LUNA_TOKEN_SLASH:
    case LUNA_TOKEN_SLASH_EQUAL:
        *opcode = LUNA_IR_DIV_FLOAT;
        return true;
    default:
        return false;
    }
}

static LunaIrOpcode
luna_sema_float_comparison_opcode(LunaTokenKind operator_kind) {
    switch (operator_kind) {
    case LUNA_TOKEN_LESS:
        return LUNA_IR_COMPARE_LESS_FLOAT;
    case LUNA_TOKEN_LESS_EQUAL:
        return LUNA_IR_COMPARE_LESS_EQUAL_FLOAT;
    case LUNA_TOKEN_GREATER:
        return LUNA_IR_COMPARE_GREATER_FLOAT;
    case LUNA_TOKEN_GREATER_EQUAL:
        return LUNA_IR_COMPARE_GREATER_EQUAL_FLOAT;
    default:
        return LUNA_IR_COMPARE_LESS_FLOAT;
    }
}

static uint64_t luna_sema_integer_maximum(const LunaSemaContext *context,
                                          LunaTypeKind type) {
    const uint32_t width =
        luna_type_kind_bit_width(type, &context->module->target->data_layout);
    if (width == 0U || width > 64U) {
        return 0U;
    }
    if (luna_type_kind_is_unsigned_integer(type)) {
        return width == 64U ? UINT64_MAX : (UINT64_C(1) << width) - 1U;
    }
    return width == 64U ? (uint64_t)INT64_MAX
                        : (UINT64_C(1) << (width - 1U)) - 1U;
}

static uint64_t
luna_sema_signed_minimum_magnitude(const LunaSemaContext *context,
                                   LunaTypeKind type) {
    if (!luna_type_kind_is_signed_integer(type)) {
        return 0U;
    }
    const uint32_t width =
        luna_type_kind_bit_width(type, &context->module->target->data_layout);
    return width == 0U || width > 64U ? 0U : UINT64_C(1) << (width - 1U);
}

static bool luna_sema_float_literal_bits(LunaSemaContext *context,
                                         const LunaExpression *expression,
                                         LunaTypeKind type, uint64_t *bits) {
    const LunaStringView text = expression->as.floating;
    if (text.length == SIZE_MAX) {
        luna_sema_report_allocation_failure(context);
        return false;
    }

    char *normalized = malloc(text.length + 1U);
    if (normalized == NULL) {
        luna_sema_report_allocation_failure(context);
        return false;
    }

    size_t normalized_length = 0U;
    for (size_t index = 0U; index < text.length; index += 1U) {
        if (text.data[index] != '_') {
            normalized[normalized_length] = text.data[index];
            normalized_length += 1U;
        }
    }
    normalized[normalized_length] = '\0';

    char *end = NULL;
    bool valid = false;
    bool finite = false;
    if (type == LUNA_TYPE_F32) {
        const float value = strtof(normalized, &end);
        uint32_t value_bits = 0U;
        memcpy(&value_bits, &value, sizeof(value_bits));
        *bits = value_bits;
        finite = isfinite(value);
        valid = end == normalized + normalized_length;
    } else if (type == LUNA_TYPE_F64) {
        const double value = strtod(normalized, &end);
        memcpy(bits, &value, sizeof(*bits));
        finite = isfinite(value);
        valid = end == normalized + normalized_length;
    }
    free(normalized);

    if (!valid) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "invalid floating-point literal");
        return false;
    }
    if (!finite) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "floating-point literal does not fit in %s",
                              luna_type_kind_name(type));
        return false;
    }
    return true;
}

static LunaCheckedValue
luna_sema_lower_expression(LunaSemaContext *context,
                           const LunaExpression *expression) {
    return luna_sema_lower_expression_expected(context, expression,
                                               LUNA_TYPE_INVALID);
}

static LunaTypeKind
luna_sema_known_expression_type(LunaSemaContext *context,
                                const LunaExpression *expression) {
    if (expression == NULL) {
        return LUNA_TYPE_INVALID;
    }

    switch (expression->kind) {
    case LUNA_EXPRESSION_INTEGER:
    case LUNA_EXPRESSION_FLOAT:
        return LUNA_TYPE_INVALID;
    case LUNA_EXPRESSION_BOOLEAN:
        return LUNA_TYPE_BOOL;
    case LUNA_EXPRESSION_NAME: {
        const LunaSemaLocal *local =
            luna_sema_find_local(context, expression->as.name);
        return local == NULL ? LUNA_TYPE_INVALID : local->type;
    }
    case LUNA_EXPRESSION_CALL: {
        const LunaSemaFunction *function =
            luna_sema_find_function(context, expression->as.call.name);
        return function == NULL ? LUNA_TYPE_INVALID
                                : function->syntax->return_type.kind;
    }
    case LUNA_EXPRESSION_CAST:
        return expression->as.cast.target_type.kind;
    case LUNA_EXPRESSION_UNARY:
        if (expression->as.unary.operator_kind == LUNA_TOKEN_BANG) {
            return LUNA_TYPE_BOOL;
        }
        return luna_sema_known_expression_type(context,
                                               expression->as.unary.operand);
    case LUNA_EXPRESSION_BINARY:
        switch (expression->as.binary.operator_kind) {
        case LUNA_TOKEN_LOGICAL_AND:
        case LUNA_TOKEN_LOGICAL_OR:
        case LUNA_TOKEN_EQUAL_EQUAL:
        case LUNA_TOKEN_BANG_EQUAL:
        case LUNA_TOKEN_LESS:
        case LUNA_TOKEN_LESS_EQUAL:
        case LUNA_TOKEN_GREATER:
        case LUNA_TOKEN_GREATER_EQUAL:
            return LUNA_TYPE_BOOL;
        default:
            break;
        }

        LunaTypeKind type = luna_sema_known_expression_type(
            context, expression->as.binary.left);
        if (type == LUNA_TYPE_INVALID) {
            type = luna_sema_known_expression_type(context,
                                                   expression->as.binary.right);
        }
        return type;
    }

    return LUNA_TYPE_INVALID;
}

static LunaTypeKind
luna_sema_default_literal_type(const LunaExpression *expression) {
    if (expression == NULL) {
        return LUNA_TYPE_INVALID;
    }

    switch (expression->kind) {
    case LUNA_EXPRESSION_INTEGER:
        return LUNA_TYPE_I32;
    case LUNA_EXPRESSION_FLOAT:
        return LUNA_TYPE_F64;
    case LUNA_EXPRESSION_UNARY:
        if (expression->as.unary.operator_kind == LUNA_TOKEN_PLUS ||
            expression->as.unary.operator_kind == LUNA_TOKEN_MINUS) {
            return luna_sema_default_literal_type(expression->as.unary.operand);
        }
        return LUNA_TYPE_INVALID;
    case LUNA_EXPRESSION_BINARY: {
        const LunaTypeKind left =
            luna_sema_default_literal_type(expression->as.binary.left);
        const LunaTypeKind right =
            luna_sema_default_literal_type(expression->as.binary.right);
        if (left == LUNA_TYPE_F64 || right == LUNA_TYPE_F64) {
            return LUNA_TYPE_F64;
        }
        if (left == LUNA_TYPE_I32 || right == LUNA_TYPE_I32) {
            return LUNA_TYPE_I32;
        }
        return LUNA_TYPE_INVALID;
    }
    case LUNA_EXPRESSION_BOOLEAN:
    case LUNA_EXPRESSION_NAME:
    case LUNA_EXPRESSION_CALL:
    case LUNA_EXPRESSION_CAST:
        return LUNA_TYPE_INVALID;
    }

    return LUNA_TYPE_INVALID;
}

static LunaCheckedValue
luna_sema_lower_logical(LunaSemaContext *context,
                        const LunaExpression *expression) {
    const bool is_and =
        expression->as.binary.operator_kind == LUNA_TOKEN_LOGICAL_AND;

    LunaCheckedValue left = luna_sema_lower_expression_expected(
        context, expression->as.binary.left, LUNA_TYPE_BOOL);
    if (!luna_sema_require_type(context, left, LUNA_TYPE_BOOL,
                                expression->as.binary.left->span)) {
        return luna_sema_invalid_value();
    }

    const LunaIrSlotId result_slot =
        luna_ir_function_add_slot(context->current_function, LUNA_IR_TYPE_BOOL);
    const LunaIrBlockId right_block = luna_sema_add_block(context);
    const LunaIrBlockId short_block = luna_sema_add_block(context);
    const LunaIrBlockId merge_block = luna_sema_add_block(context);

    if (result_slot == LUNA_IR_INVALID_ID ||
        right_block == LUNA_IR_INVALID_ID ||
        short_block == LUNA_IR_INVALID_ID ||
        merge_block == LUNA_IR_INVALID_ID) {
        luna_sema_report_allocation_failure(context);
        return luna_sema_invalid_value();
    }

    if (is_and) {
        (void)luna_sema_emit_branch(context, left.id, right_block, short_block,
                                    expression->span);
    } else {
        (void)luna_sema_emit_branch(context, left.id, short_block, right_block,
                                    expression->span);
    }

    luna_sema_set_block(context, short_block);
    LunaIrInstruction short_value =
        luna_sema_instruction(LUNA_IR_CONST_BOOL, expression->span);
    short_value.immediate = is_and ? 0 : 1;
    const LunaIrValueId short_id =
        luna_sema_emit_value_instruction(context, &short_value, LUNA_TYPE_BOOL);

    LunaIrInstruction short_store =
        luna_sema_instruction(LUNA_IR_STORE, expression->span);
    short_store.slot = result_slot;
    short_store.left = short_id;
    (void)luna_sema_append_instruction(context, &short_store);
    (void)luna_sema_emit_jump(context, merge_block, expression->span);

    luna_sema_set_block(context, right_block);
    LunaCheckedValue right = luna_sema_lower_expression_expected(
        context, expression->as.binary.right, LUNA_TYPE_BOOL);
    if (!luna_sema_require_type(context, right, LUNA_TYPE_BOOL,
                                expression->as.binary.right->span)) {
        return luna_sema_invalid_value();
    }

    LunaIrInstruction right_store =
        luna_sema_instruction(LUNA_IR_STORE, expression->span);
    right_store.slot = result_slot;
    right_store.left = right.id;
    (void)luna_sema_append_instruction(context, &right_store);
    (void)luna_sema_emit_jump(context, merge_block, expression->span);

    luna_sema_set_block(context, merge_block);
    LunaIrInstruction load =
        luna_sema_instruction(LUNA_IR_LOAD, expression->span);
    load.slot = result_slot;
    const LunaIrValueId result =
        luna_sema_emit_value_instruction(context, &load, LUNA_TYPE_BOOL);

    return (LunaCheckedValue){
        .id = result,
        .type = LUNA_TYPE_BOOL,
    };
}

static LunaCheckedValue luna_sema_lower_call(LunaSemaContext *context,
                                             const LunaExpression *expression) {
    LunaSemaFunction *callee =
        luna_sema_find_function(context, expression->as.call.name);
    if (callee == NULL) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "unknown function '%.*s'",
                              (int)expression->as.call.name.length,
                              expression->as.call.name.data);
        return luna_sema_invalid_value();
    }

    if (expression->as.call.argument_count != callee->syntax->parameter_count) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "function '%.*s' expects %u arguments, found %u",
                              (int)callee->syntax->name.length,
                              callee->syntax->name.data,
                              callee->syntax->parameter_count,
                              expression->as.call.argument_count);
        return luna_sema_invalid_value();
    }

    LunaVector arguments;
    luna_vector_init(&arguments, sizeof(LunaIrValueId));

    const LunaExpression *argument = expression->as.call.first_argument;
    const LunaParameter *parameter = callee->syntax->first_parameter;
    while (argument != NULL && parameter != NULL) {
        LunaCheckedValue value = luna_sema_lower_expression_expected(
            context, argument, parameter->type.kind);
        if (!luna_sema_require_type(context, value, parameter->type.kind,
                                    argument->span)) {
            luna_vector_destroy(&arguments);
            return luna_sema_invalid_value();
        }

        if (!luna_vector_push(&arguments, &value.id)) {
            luna_sema_report_allocation_failure(context);
            luna_vector_destroy(&arguments);
            return luna_sema_invalid_value();
        }

        argument = argument->next;
        parameter = parameter->next;
    }

    if (arguments.length > UINT32_MAX ||
        context->current_function->arguments.length >
            UINT32_MAX - arguments.length) {
        luna_sema_report_allocation_failure(context);
        luna_vector_destroy(&arguments);
        return luna_sema_invalid_value();
    }

    const uint32_t first_argument =
        (uint32_t)context->current_function->arguments.length;
    for (size_t index = 0U; index < arguments.length; index += 1U) {
        const LunaIrValueId *value = luna_vector_at_const(&arguments, index);
        if (!luna_vector_push(&context->current_function->arguments, value)) {
            luna_sema_report_allocation_failure(context);
            luna_vector_destroy(&arguments);
            return luna_sema_invalid_value();
        }
    }
    luna_vector_destroy(&arguments);

    LunaIrInstruction call =
        luna_sema_instruction(LUNA_IR_CALL, expression->span);
    call.callee = callee->ir_id;
    call.first_argument = first_argument;
    call.argument_count = expression->as.call.argument_count;

    const LunaTypeKind return_type = callee->syntax->return_type.kind;
    if (return_type == LUNA_TYPE_VOID) {
        if (!luna_sema_append_instruction(context, &call)) {
            return luna_sema_invalid_value();
        }

        return (LunaCheckedValue){
            .id = LUNA_IR_INVALID_ID,
            .type = LUNA_TYPE_VOID,
        };
    }

    const LunaIrValueId result =
        luna_sema_emit_value_instruction(context, &call, return_type);
    return (LunaCheckedValue){
        .id = result,
        .type = return_type,
    };
}

static LunaCheckedValue
luna_sema_lower_expression_expected(LunaSemaContext *context,
                                    const LunaExpression *expression,
                                    LunaTypeKind expected_type) {
    if (expression == NULL || !context->reachable) {
        return luna_sema_invalid_value();
    }

    switch (expression->kind) {
    case LUNA_EXPRESSION_INTEGER: {
        const LunaTypeKind literal_type =
            luna_sema_is_integer_type(expected_type) ? expected_type
                                                     : LUNA_TYPE_I32;
        const uint64_t maximum =
            luna_sema_integer_maximum(context, literal_type);
        if (expression->as.integer > maximum) {
            luna_diagnostic_error(context->diagnostics, expression->span,
                                  "integer literal does not fit in %s",
                                  luna_type_kind_name(literal_type));
            return luna_sema_invalid_value();
        }

        LunaIrInstruction instruction =
            luna_sema_instruction(LUNA_IR_CONST_INTEGER, expression->span);
        instruction.immediate = expression->as.integer;
        const LunaIrValueId result = luna_sema_emit_value_instruction(
            context, &instruction, literal_type);
        return (LunaCheckedValue){
            .id = result,
            .type = literal_type,
        };
    }

    case LUNA_EXPRESSION_FLOAT: {
        const LunaTypeKind literal_type = luna_sema_is_float_type(expected_type)
                                              ? expected_type
                                              : LUNA_TYPE_F64;
        uint64_t bits = 0U;
        if (!luna_sema_float_literal_bits(context, expression, literal_type,
                                          &bits)) {
            return luna_sema_invalid_value();
        }

        LunaIrInstruction instruction =
            luna_sema_instruction(LUNA_IR_CONST_FLOAT, expression->span);
        instruction.immediate = bits;
        const LunaIrValueId result = luna_sema_emit_value_instruction(
            context, &instruction, literal_type);
        return (LunaCheckedValue){
            .id = result,
            .type = literal_type,
        };
    }

    case LUNA_EXPRESSION_BOOLEAN: {
        LunaIrInstruction instruction =
            luna_sema_instruction(LUNA_IR_CONST_BOOL, expression->span);
        instruction.immediate = expression->as.boolean ? 1 : 0;
        const LunaIrValueId result = luna_sema_emit_value_instruction(
            context, &instruction, LUNA_TYPE_BOOL);
        return (LunaCheckedValue){
            .id = result,
            .type = LUNA_TYPE_BOOL,
        };
    }

    case LUNA_EXPRESSION_NAME: {
        LunaSemaLocal *local =
            luna_sema_find_local(context, expression->as.name);
        if (local == NULL) {
            luna_diagnostic_error(context->diagnostics, expression->span,
                                  "unknown local variable '%.*s'",
                                  (int)expression->as.name.length,
                                  expression->as.name.data);
            return luna_sema_invalid_value();
        }

        LunaIrInstruction load =
            luna_sema_instruction(LUNA_IR_LOAD, expression->span);
        load.slot = local->slot;
        const LunaIrValueId result =
            luna_sema_emit_value_instruction(context, &load, local->type);
        return (LunaCheckedValue){
            .id = result,
            .type = local->type,
        };
    }

    case LUNA_EXPRESSION_CALL:
        return luna_sema_lower_call(context, expression);

    case LUNA_EXPRESSION_CAST: {
        const LunaTypeKind target_type = expression->as.cast.target_type.kind;
        const LunaTypeKind operand_hint = luna_sema_known_expression_type(
            context, expression->as.cast.operand);
        LunaCheckedValue operand =
            operand_hint == LUNA_TYPE_INVALID
                ? luna_sema_lower_expression_expected(
                      context, expression->as.cast.operand, target_type)
                : luna_sema_lower_expression(context,
                                             expression->as.cast.operand);
        if (!luna_sema_is_integer_type(operand.type) ||
            !luna_sema_is_integer_type(target_type)) {
            luna_diagnostic_error(
                context->diagnostics, expression->span,
                "explicit conversion requires integer source and target types");
            return luna_sema_invalid_value();
        }

        if (operand.type == target_type) {
            return operand;
        }

        LunaIrInstruction instruction =
            luna_sema_instruction(LUNA_IR_CONVERT_INTEGER, expression->span);
        instruction.left = operand.id;
        const LunaIrValueId result = luna_sema_emit_value_instruction(
            context, &instruction, target_type);
        return (LunaCheckedValue){
            .id = result,
            .type = target_type,
        };
    }

    case LUNA_EXPRESSION_UNARY: {
        LunaTypeKind operand_type = expected_type;
        if (!luna_sema_is_numeric_type(operand_type)) {
            operand_type = luna_sema_known_expression_type(
                context, expression->as.unary.operand);
        }
        if (!luna_sema_is_numeric_type(operand_type)) {
            operand_type =
                luna_sema_default_literal_type(expression->as.unary.operand);
        }
        if (!luna_sema_is_numeric_type(operand_type)) {
            operand_type = LUNA_TYPE_I32;
        }

        if (expression->as.unary.operator_kind == LUNA_TOKEN_MINUS &&
            luna_type_kind_is_signed_integer(operand_type) &&
            expression->as.unary.operand->kind == LUNA_EXPRESSION_INTEGER &&
            expression->as.unary.operand->as.integer ==
                luna_sema_signed_minimum_magnitude(context, operand_type)) {
            LunaIrInstruction instruction =
                luna_sema_instruction(LUNA_IR_CONST_INTEGER, expression->span);
            instruction.immediate = expression->as.unary.operand->as.integer;
            const LunaIrValueId result = luna_sema_emit_value_instruction(
                context, &instruction, operand_type);
            return (LunaCheckedValue){
                .id = result,
                .type = operand_type,
            };
        }

        const LunaTypeKind required_type =
            expression->as.unary.operator_kind == LUNA_TOKEN_BANG
                ? LUNA_TYPE_BOOL
                : operand_type;
        LunaCheckedValue operand = luna_sema_lower_expression_expected(
            context, expression->as.unary.operand, required_type);

        switch (expression->as.unary.operator_kind) {
        case LUNA_TOKEN_PLUS:
            if (!luna_sema_is_numeric_type(operand.type)) {
                luna_diagnostic_error(context->diagnostics, expression->span,
                                      "unary '+' requires a numeric operand");
                return luna_sema_invalid_value();
            }
            if (!luna_sema_require_type(context, operand, required_type,
                                        expression->span)) {
                return luna_sema_invalid_value();
            }
            return operand;

        case LUNA_TOKEN_MINUS:
            if (!luna_sema_is_numeric_type(operand.type)) {
                luna_diagnostic_error(context->diagnostics, expression->span,
                                      "unary '-' requires a numeric operand");
                return luna_sema_invalid_value();
            }
            if (!luna_sema_require_type(context, operand, required_type,
                                        expression->as.unary.operand->span)) {
                return luna_sema_invalid_value();
            }
            break;

        case LUNA_TOKEN_TILDE:
            if (!luna_sema_is_integer_type(operand.type)) {
                luna_diagnostic_error(context->diagnostics, expression->span,
                                      "unary '~' requires an integer operand");
                return luna_sema_invalid_value();
            }
            if (!luna_sema_require_type(context, operand, required_type,
                                        expression->as.unary.operand->span)) {
                return luna_sema_invalid_value();
            }
            break;

        case LUNA_TOKEN_BANG:
            if (!luna_sema_require_type(context, operand, LUNA_TYPE_BOOL,
                                        expression->as.unary.operand->span)) {
                return luna_sema_invalid_value();
            }
            break;

        default:
            return luna_sema_invalid_value();
        }

        const LunaTypeKind result_type =
            expression->as.unary.operator_kind == LUNA_TOKEN_BANG
                ? LUNA_TYPE_BOOL
                : operand.type;
        LunaIrOpcode opcode = LUNA_IR_BOOL_NOT;
        if (expression->as.unary.operator_kind == LUNA_TOKEN_MINUS) {
            opcode = luna_sema_is_float_type(operand.type)
                         ? LUNA_IR_NEG_FLOAT
                         : LUNA_IR_NEG_INTEGER;
        } else if (expression->as.unary.operator_kind == LUNA_TOKEN_TILDE) {
            opcode = LUNA_IR_BIT_NOT_INTEGER;
        }

        LunaIrInstruction instruction =
            luna_sema_instruction(opcode, expression->span);
        instruction.left = operand.id;
        const LunaIrValueId result = luna_sema_emit_value_instruction(
            context, &instruction, result_type);
        return (LunaCheckedValue){
            .id = result,
            .type = result_type,
        };
    }

    case LUNA_EXPRESSION_BINARY:
        break;
    }

    if (expression->as.binary.operator_kind == LUNA_TOKEN_LOGICAL_AND ||
        expression->as.binary.operator_kind == LUNA_TOKEN_LOGICAL_OR) {
        return luna_sema_lower_logical(context, expression);
    }

    const LunaTokenKind operator_kind = expression->as.binary.operator_kind;
    const bool is_equality = operator_kind == LUNA_TOKEN_EQUAL_EQUAL ||
                             operator_kind == LUNA_TOKEN_BANG_EQUAL;
    const bool is_relational = operator_kind == LUNA_TOKEN_LESS ||
                               operator_kind == LUNA_TOKEN_LESS_EQUAL ||
                               operator_kind == LUNA_TOKEN_GREATER ||
                               operator_kind == LUNA_TOKEN_GREATER_EQUAL;

    LunaTypeKind operand_type = LUNA_TYPE_INVALID;
    if (!is_equality && !is_relational &&
        luna_sema_is_numeric_type(expected_type)) {
        operand_type = expected_type;
    }
    if (operand_type == LUNA_TYPE_INVALID) {
        operand_type = luna_sema_known_expression_type(
            context, expression->as.binary.left);
    }
    if (operand_type == LUNA_TYPE_INVALID) {
        operand_type = luna_sema_known_expression_type(
            context, expression->as.binary.right);
    }
    if (operand_type == LUNA_TYPE_INVALID) {
        operand_type =
            luna_sema_default_literal_type(expression->as.binary.left);
        if (operand_type == LUNA_TYPE_INVALID) {
            operand_type =
                luna_sema_default_literal_type(expression->as.binary.right);
        }
    }
    if (operand_type == LUNA_TYPE_INVALID) {
        operand_type = LUNA_TYPE_I32;
    }

    LunaCheckedValue left = luna_sema_lower_expression_expected(
        context, expression->as.binary.left, operand_type);
    LunaCheckedValue right = luna_sema_lower_expression_expected(
        context, expression->as.binary.right, operand_type);
    if (!luna_sema_require_type(context, left, operand_type,
                                expression->as.binary.left->span) ||
        !luna_sema_require_type(context, right, operand_type,
                                expression->as.binary.right->span)) {
        return luna_sema_invalid_value();
    }

    if (is_equality && operand_type != LUNA_TYPE_BOOL &&
        !luna_sema_is_numeric_type(operand_type)) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "equality requires bool or numeric operands");
        return luna_sema_invalid_value();
    }
    if (is_relational && !luna_sema_is_numeric_type(operand_type)) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "ordering requires numeric operands");
        return luna_sema_invalid_value();
    }
    if (!is_equality && !is_relational &&
        !luna_sema_is_numeric_type(operand_type)) {
        luna_diagnostic_error(context->diagnostics, expression->span,
                              "arithmetic and bitwise operators require "
                              "numeric operands");
        return luna_sema_invalid_value();
    }

    LunaIrOpcode opcode = LUNA_IR_ADD_INTEGER;
    if (is_equality) {
        opcode = operator_kind == LUNA_TOKEN_EQUAL_EQUAL
                     ? LUNA_IR_COMPARE_EQUAL
                     : LUNA_IR_COMPARE_NOT_EQUAL;
    } else if (is_relational) {
        opcode = luna_sema_is_float_type(operand_type)
                     ? luna_sema_float_comparison_opcode(operator_kind)
                     : luna_sema_binary_integer_opcode(operator_kind);
    } else if (luna_sema_is_float_type(operand_type)) {
        if (!luna_sema_binary_float_opcode(operator_kind, &opcode)) {
            luna_diagnostic_error(
                context->diagnostics, expression->span,
                "operator %s is not defined for floating-point operands",
                luna_token_kind_name(operator_kind));
            return luna_sema_invalid_value();
        }
    } else {
        opcode = luna_sema_binary_integer_opcode(operator_kind);
    }
    const LunaTypeKind result_type =
        is_equality || is_relational ? LUNA_TYPE_BOOL : operand_type;

    LunaIrInstruction instruction =
        luna_sema_instruction(opcode, expression->span);
    instruction.left = left.id;
    instruction.right = right.id;
    const LunaIrValueId result =
        luna_sema_emit_value_instruction(context, &instruction, result_type);
    return (LunaCheckedValue){
        .id = result,
        .type = result_type,
    };
}

static bool luna_sema_lower_statement(LunaSemaContext *context,
                                      const LunaStatement *statement);

static void luna_sema_lower_block(LunaSemaContext *context,
                                  const LunaBlock *block, bool create_scope) {
    if (block == NULL) {
        return;
    }

    if (create_scope) {
        luna_sema_enter_scope(context);
    }

    bool owns_dead_region = false;
    for (const LunaStatement *statement = block->first; statement != NULL;
         statement = statement->next) {
        if (!context->reachable) {
            const LunaIrBlockId dead_block = luna_sema_add_block(context);
            if (dead_block == LUNA_IR_INVALID_ID) {
                break;
            }

            context->current_block = dead_block;
            context->reachable = true;
            if (!context->checking_dead_code) {
                context->checking_dead_code = true;
                owns_dead_region = true;
            }
        }

        (void)luna_sema_lower_statement(context, statement);
    }

    if (owns_dead_region) {
        if (context->reachable) {
            (void)luna_sema_emit_jump(context, context->current_block,
                                      block->span);
        }
        context->checking_dead_code = false;
        context->reachable = false;
    }

    if (create_scope) {
        luna_sema_leave_scope(context);
    }
}

static bool luna_sema_lower_if(LunaSemaContext *context,
                               const LunaStatement *statement) {
    LunaCheckedValue condition = luna_sema_lower_expression_expected(
        context, statement->as.if_statement.condition, LUNA_TYPE_BOOL);
    if (!luna_sema_require_type(context, condition, LUNA_TYPE_BOOL,
                                statement->as.if_statement.condition->span)) {
        return false;
    }

    const LunaIrBlockId then_block = luna_sema_add_block(context);
    const LunaIrBlockId else_block = luna_sema_add_block(context);
    const LunaIrBlockId merge_block = luna_sema_add_block(context);
    if (then_block == LUNA_IR_INVALID_ID || else_block == LUNA_IR_INVALID_ID ||
        merge_block == LUNA_IR_INVALID_ID) {
        return false;
    }

    (void)luna_sema_emit_branch(context, condition.id, then_block, else_block,
                                statement->span);

    luna_sema_set_block(context, then_block);
    luna_sema_lower_block(context, statement->as.if_statement.then_block, true);
    const bool then_falls_through = context->reachable;
    if (then_falls_through) {
        (void)luna_sema_emit_jump(context, merge_block, statement->span);
    }

    luna_sema_set_block(context, else_block);
    if (statement->as.if_statement.else_branch != NULL) {
        (void)luna_sema_lower_statement(context,
                                        statement->as.if_statement.else_branch);
    }
    const bool else_falls_through = context->reachable;
    if (else_falls_through) {
        (void)luna_sema_emit_jump(context, merge_block, statement->span);
    }

    luna_sema_set_block(context, merge_block);
    context->reachable = then_falls_through || else_falls_through;
    return true;
}

static bool luna_sema_lower_while(LunaSemaContext *context,
                                  const LunaStatement *statement) {
    const LunaIrBlockId condition_block = luna_sema_add_block(context);
    const LunaIrBlockId body_block = luna_sema_add_block(context);
    const LunaIrBlockId exit_block = luna_sema_add_block(context);
    if (condition_block == LUNA_IR_INVALID_ID ||
        body_block == LUNA_IR_INVALID_ID || exit_block == LUNA_IR_INVALID_ID) {
        return false;
    }

    (void)luna_sema_emit_jump(context, condition_block, statement->span);

    luna_sema_set_block(context, condition_block);
    LunaCheckedValue condition = luna_sema_lower_expression_expected(
        context, statement->as.while_statement.condition, LUNA_TYPE_BOOL);
    if (!luna_sema_require_type(
            context, condition, LUNA_TYPE_BOOL,
            statement->as.while_statement.condition->span)) {
        return false;
    }
    (void)luna_sema_emit_branch(context, condition.id, body_block, exit_block,
                                statement->span);

    const LunaSemaLoop loop = {
        .continue_block = condition_block,
        .break_block = exit_block,
    };
    if (!luna_vector_push(&context->loops, &loop)) {
        luna_sema_report_allocation_failure(context);
        return false;
    }

    luna_sema_set_block(context, body_block);
    luna_sema_lower_block(context, statement->as.while_statement.body, true);
    if (context->reachable) {
        (void)luna_sema_emit_jump(context, condition_block, statement->span);
    }
    context->loops.length -= 1U;

    luna_sema_set_block(context, exit_block);
    context->reachable = true;
    return true;
}

static bool luna_sema_lower_statement(LunaSemaContext *context,
                                      const LunaStatement *statement) {
    switch (statement->kind) {
    case LUNA_STATEMENT_BLOCK:
        luna_sema_lower_block(context, &statement->as.block, true);
        return true;

    case LUNA_STATEMENT_DECLARATION: {
        if (statement->as.declaration.type.kind == LUNA_TYPE_VOID) {
            luna_diagnostic_error(context->diagnostics,
                                  statement->as.declaration.type.span,
                                  "local variables cannot have type void");
            return false;
        }

        if (luna_sema_find_local_in_current_scope(
                context, statement->as.declaration.name) != NULL) {
            luna_diagnostic_error(context->diagnostics, statement->span,
                                  "duplicate local variable '%.*s'",
                                  (int)statement->as.declaration.name.length,
                                  statement->as.declaration.name.data);
            return false;
        }

        LunaCheckedValue initializer = luna_sema_lower_expression_expected(
            context, statement->as.declaration.initializer,
            statement->as.declaration.type.kind);
        if (!luna_sema_require_type(
                context, initializer, statement->as.declaration.type.kind,
                statement->as.declaration.initializer->span)) {
            return false;
        }

        const LunaIrSlotId slot = luna_ir_function_add_slot(
            context->current_function,
            luna_sema_ir_type(statement->as.declaration.type.kind));
        if (slot == LUNA_IR_INVALID_ID) {
            luna_sema_report_allocation_failure(context);
            return false;
        }

        if (!luna_sema_add_local(context, statement->as.declaration.name,
                                 statement->as.declaration.type.kind, slot,
                                 statement->as.declaration.is_mutable)) {
            return false;
        }

        LunaIrInstruction store =
            luna_sema_instruction(LUNA_IR_STORE, statement->span);
        store.slot = slot;
        store.left = initializer.id;
        return luna_sema_append_instruction(context, &store);
    }

    case LUNA_STATEMENT_ASSIGNMENT: {
        LunaSemaLocal *local =
            luna_sema_find_local(context, statement->as.assignment.name);
        if (local == NULL) {
            luna_diagnostic_error(context->diagnostics, statement->span,
                                  "unknown local variable '%.*s'",
                                  (int)statement->as.assignment.name.length,
                                  statement->as.assignment.name.data);
            return false;
        }

        if (!local->is_mutable) {
            luna_diagnostic_error(context->diagnostics, statement->span,
                                  "cannot assign to immutable local '%.*s'",
                                  (int)local->name.length, local->name.data);
            return false;
        }

        LunaCheckedValue value = luna_sema_lower_expression_expected(
            context, statement->as.assignment.value, local->type);
        if (!luna_sema_require_type(context, value, local->type,
                                    statement->as.assignment.value->span)) {
            return false;
        }

        if (statement->as.assignment.operator_kind != LUNA_TOKEN_EQUAL) {
            if (!luna_sema_is_numeric_type(local->type)) {
                luna_diagnostic_error(
                    context->diagnostics, statement->span,
                    "compound assignment requires a numeric type");
                return false;
            }

            LunaIrInstruction load =
                luna_sema_instruction(LUNA_IR_LOAD, statement->span);
            load.slot = local->slot;
            const LunaIrValueId current =
                luna_sema_emit_value_instruction(context, &load, local->type);

            LunaIrOpcode opcode = LUNA_IR_ADD_INTEGER;
            if (luna_sema_is_float_type(local->type) &&
                !luna_sema_binary_float_opcode(
                    statement->as.assignment.operator_kind, &opcode)) {
                luna_diagnostic_error(
                    context->diagnostics, statement->span,
                    "operator %s is not defined for floating-point operands",
                    luna_token_kind_name(
                        statement->as.assignment.operator_kind));
                return false;
            }
            if (luna_sema_is_integer_type(local->type)) {
                opcode = luna_sema_binary_integer_opcode(
                    statement->as.assignment.operator_kind);
            }

            LunaIrInstruction operation =
                luna_sema_instruction(opcode, statement->span);
            operation.left = current;
            operation.right = value.id;
            value.id = luna_sema_emit_value_instruction(context, &operation,
                                                        local->type);
        }

        LunaIrInstruction store =
            luna_sema_instruction(LUNA_IR_STORE, statement->span);
        store.slot = local->slot;
        store.left = value.id;
        return luna_sema_append_instruction(context, &store);
    }

    case LUNA_STATEMENT_EXPRESSION:
        (void)luna_sema_lower_expression(context, statement->as.expression);
        return true;

    case LUNA_STATEMENT_IF:
        return luna_sema_lower_if(context, statement);

    case LUNA_STATEMENT_WHILE:
        return luna_sema_lower_while(context, statement);

    case LUNA_STATEMENT_BREAK:
    case LUNA_STATEMENT_CONTINUE: {
        if (context->loops.length == 0U) {
            luna_diagnostic_error(
                context->diagnostics, statement->span,
                "%s is only valid inside a loop",
                statement->kind == LUNA_STATEMENT_BREAK ? "break" : "continue");
            return false;
        }

        const LunaSemaLoop *loop =
            luna_vector_at_const(&context->loops, context->loops.length - 1U);
        return luna_sema_emit_jump(context,
                                   statement->kind == LUNA_STATEMENT_BREAK
                                       ? loop->break_block
                                       : loop->continue_block,
                                   statement->span);
    }

    case LUNA_STATEMENT_RETURN: {
        const LunaTypeKind expected =
            context->current_syntax_function->return_type.kind;
        LunaIrInstruction instruction =
            luna_sema_instruction(LUNA_IR_RETURN, statement->span);

        if (statement->as.return_value == NULL) {
            if (expected != LUNA_TYPE_VOID) {
                luna_diagnostic_error(
                    context->diagnostics, statement->span,
                    "function returning %s requires a return value",
                    luna_type_kind_name(expected));
                return false;
            }
        } else {
            LunaCheckedValue value = luna_sema_lower_expression_expected(
                context, statement->as.return_value, expected);
            if (!luna_sema_require_type(context, value, expected,
                                        statement->as.return_value->span)) {
                return false;
            }
            instruction.left = value.id;
        }

        if (!luna_sema_append_instruction(context, &instruction)) {
            return false;
        }
        context->reachable = false;
        return true;
    }
    }

    return false;
}

static bool luna_sema_collect_functions(LunaSemaContext *context) {
    for (const LunaFunction *syntax = context->program->first_function;
         syntax != NULL; syntax = syntax->next) {
        if (syntax->is_declaration) {
            luna_diagnostic_error(
                context->diagnostics, syntax->span,
                "separate module interface implementations are scheduled "
                "for milestone M2");
            continue;
        }

        if (luna_sema_find_function(context, syntax->name) != NULL) {
            luna_diagnostic_error(context->diagnostics, syntax->span,
                                  "duplicate function '%.*s'",
                                  (int)syntax->name.length, syntax->name.data);
            continue;
        }

        uint32_t integer_parameter_count = 0U;
        uint32_t float_parameter_count = 0U;
        for (const LunaParameter *parameter = syntax->first_parameter;
             parameter != NULL; parameter = parameter->next) {
            if (luna_sema_is_float_type(parameter->type.kind)) {
                float_parameter_count += 1U;
            } else if (parameter->type.kind != LUNA_TYPE_VOID &&
                       parameter->type.kind != LUNA_TYPE_INVALID) {
                integer_parameter_count += 1U;
            }
        }
        if (integer_parameter_count > 6U || float_parameter_count > 8U) {
            luna_diagnostic_error(
                context->diagnostics, syntax->span,
                "the bootstrap ABI supports at most six integer-class and "
                "eight floating-point arguments");
            continue;
        }

        const LunaIrFunctionId ir_id = luna_ir_module_add_function(
            context->module, context->program->module_name, syntax->name,
            luna_sema_ir_type(syntax->return_type.kind));
        if (ir_id == LUNA_IR_INVALID_ID) {
            luna_sema_report_allocation_failure(context);
            return false;
        }

        LunaIrFunction *ir_function =
            luna_ir_module_function(context->module, ir_id);
        for (const LunaParameter *parameter = syntax->first_parameter;
             parameter != NULL; parameter = parameter->next) {
            if (parameter->type.kind == LUNA_TYPE_VOID ||
                parameter->type.kind == LUNA_TYPE_INVALID) {
                luna_diagnostic_error(
                    context->diagnostics, parameter->span,
                    "parameter '%.*s' has invalid type %s",
                    (int)parameter->name.length, parameter->name.data,
                    luna_type_kind_name(parameter->type.kind));
                continue;
            }

            const LunaIrType type = luna_sema_ir_type(parameter->type.kind);
            if (!luna_vector_push(&ir_function->parameter_types, &type)) {
                luna_sema_report_allocation_failure(context);
                return false;
            }
            if (luna_ir_function_add_slot(ir_function, type) ==
                LUNA_IR_INVALID_ID) {
                luna_sema_report_allocation_failure(context);
                return false;
            }
        }

        const LunaSemaFunction function = {
            .syntax = syntax,
            .ir_id = ir_id,
        };
        if (!luna_vector_push(&context->functions, &function)) {
            luna_sema_report_allocation_failure(context);
            return false;
        }
    }

    return true;
}

static bool luna_sema_find_entry(LunaSemaContext *context) {
    LunaSemaFunction *entry = luna_sema_find_function(
        context, luna_string_view_from_c_string("main"));
    if (entry == NULL) {
        luna_diagnostic_error_plain(context->diagnostics,
                                    "program has no main function");
        return false;
    }

    if (entry->syntax->parameter_count != 0U ||
        entry->syntax->return_type.kind != LUNA_TYPE_I32) {
        luna_diagnostic_error(
            context->diagnostics, entry->syntax->span,
            "bootstrap entry point must be 'fn main() -> i32'");
        return false;
    }

    context->module->entry_function = entry->ir_id;
    return true;
}

static void luna_sema_lower_function(LunaSemaContext *context,
                                     LunaSemaFunction *function) {
    context->current_function =
        luna_ir_module_function(context->module, function->ir_id);
    context->current_syntax_function = function->syntax;
    context->locals.length = 0U;
    context->loops.length = 0U;
    context->scope_depth = 0U;
    context->checking_dead_code = false;

    const LunaIrBlockId entry_block = luna_sema_add_block(context);
    if (entry_block == LUNA_IR_INVALID_ID) {
        return;
    }
    context->current_block = entry_block;
    context->reachable = true;

    uint32_t parameter_index = 0U;
    for (const LunaParameter *parameter = function->syntax->first_parameter;
         parameter != NULL; parameter = parameter->next) {
        if (luna_sema_find_local_in_current_scope(context, parameter->name) !=
            NULL) {
            luna_diagnostic_error(context->diagnostics, parameter->span,
                                  "duplicate parameter '%.*s'",
                                  (int)parameter->name.length,
                                  parameter->name.data);
            continue;
        }

        (void)luna_sema_add_local(context, parameter->name,
                                  parameter->type.kind, parameter_index, false);
        parameter_index += 1U;
    }

    luna_sema_lower_block(context, function->syntax->body, true);

    if (context->reachable) {
        if (function->syntax->return_type.kind == LUNA_TYPE_VOID) {
            LunaIrInstruction return_instruction =
                luna_sema_instruction(LUNA_IR_RETURN, function->syntax->span);
            (void)luna_sema_append_instruction(context, &return_instruction);
            context->reachable = false;
        } else {
            luna_diagnostic_error(
                context->diagnostics, function->syntax->span,
                "not every path in function '%.*s' returns %s",
                (int)function->syntax->name.length, function->syntax->name.data,
                luna_type_kind_name(function->syntax->return_type.kind));
        }
    }
}

bool luna_sema_lower(const LunaProgram *program,
                     LunaDiagnosticEngine *diagnostics, LunaIrModule *module) {
    if (module == NULL || module->target == NULL ||
        !luna_data_layout_is_valid(&module->target->data_layout)) {
        luna_diagnostic_error_plain(
            diagnostics, "semantic lowering requires a valid target layout");
        return false;
    }

    LunaSemaContext context = {
        .program = program,
        .diagnostics = diagnostics,
        .module = module,
    };
    luna_vector_init(&context.functions, sizeof(LunaSemaFunction));
    luna_vector_init(&context.locals, sizeof(LunaSemaLocal));
    luna_vector_init(&context.loops, sizeof(LunaSemaLoop));

    if (program->is_interface) {
        luna_diagnostic_error(
            diagnostics, program->module_span,
            "module interface compilation is scheduled for milestone M2");
    }

    if (program->first_import != NULL) {
        luna_diagnostic_error(
            diagnostics, program->first_import->span,
            "cross-module import resolution is scheduled for milestone M2");
    }

    (void)luna_sema_collect_functions(&context);
    (void)luna_sema_find_entry(&context);

    if (luna_diagnostic_error_count(diagnostics) == 0U) {
        for (size_t index = 0U; index < context.functions.length; index += 1U) {
            LunaSemaFunction *function =
                luna_vector_at(&context.functions, index);
            luna_sema_lower_function(&context, function);
        }
    }

    const bool success = luna_diagnostic_error_count(diagnostics) == 0U &&
                         !context.allocation_failed;

    luna_vector_destroy(&context.functions);
    luna_vector_destroy(&context.locals);
    luna_vector_destroy(&context.loops);
    return success;
}

#include "luna/target/target.h"

#include <stddef.h>
#include <string.h>

static const LunaTargetInfo luna_x86_64_unknown_linux_gnu = {
    .triple = LUNA_TARGET_TRIPLE_X86_64_UNKNOWN_LINUX_GNU,
    .architecture = LUNA_TARGET_ARCHITECTURE_X86_64,
    .operating_system = LUNA_TARGET_OPERATING_SYSTEM_LINUX,
    .abi = LUNA_TARGET_ABI_SYSTEM_V,
    .data_layout =
        {
            .byte_order = LUNA_BYTE_ORDER_LITTLE_ENDIAN,
            .boolean = {.size_bits = 8U, .abi_alignment_bits = 8U},
            .integer8 = {.size_bits = 8U, .abi_alignment_bits = 8U},
            .integer16 = {.size_bits = 16U, .abi_alignment_bits = 16U},
            .integer32 = {.size_bits = 32U, .abi_alignment_bits = 32U},
            .integer64 = {.size_bits = 64U, .abi_alignment_bits = 64U},
            .float32 = {.size_bits = 32U, .abi_alignment_bits = 32U},
            .float64 = {.size_bits = 64U, .abi_alignment_bits = 64U},
            .pointer = {.size_bits = 64U, .abi_alignment_bits = 64U},
        },
};

static bool luna_scalar_layout_is_valid(const LunaScalarLayout *layout,
                                        uint32_t expected_size_bits) {
    if (layout->size_bits != expected_size_bits ||
        layout->abi_alignment_bits == 0U ||
        layout->abi_alignment_bits % 8U != 0U) {
        return false;
    }

    const uint32_t alignment = layout->abi_alignment_bits;
    return (alignment & (alignment - 1U)) == 0U;
}

const LunaTargetInfo *luna_target_info_default(void) {
    return &luna_x86_64_unknown_linux_gnu;
}

const LunaTargetInfo *luna_target_info_from_triple(const char *triple) {
    if (triple != NULL &&
        strcmp(triple, LUNA_TARGET_TRIPLE_X86_64_UNKNOWN_LINUX_GNU) == 0) {
        return &luna_x86_64_unknown_linux_gnu;
    }
    return NULL;
}

bool luna_target_info_is_supported(const LunaTargetInfo *target) {
    return target != NULL && target->triple != NULL &&
           strcmp(target->triple,
                  LUNA_TARGET_TRIPLE_X86_64_UNKNOWN_LINUX_GNU) == 0 &&
           target->architecture == LUNA_TARGET_ARCHITECTURE_X86_64 &&
           target->operating_system == LUNA_TARGET_OPERATING_SYSTEM_LINUX &&
           target->abi == LUNA_TARGET_ABI_SYSTEM_V &&
           luna_data_layout_equal(&target->data_layout,
                                  &luna_x86_64_unknown_linux_gnu.data_layout);
}

bool luna_data_layout_is_valid(const LunaDataLayout *layout) {
    if (layout == NULL ||
        (layout->byte_order != LUNA_BYTE_ORDER_LITTLE_ENDIAN &&
         layout->byte_order != LUNA_BYTE_ORDER_BIG_ENDIAN) ||
        !luna_scalar_layout_is_valid(&layout->boolean, 8U) ||
        !luna_scalar_layout_is_valid(&layout->integer8, 8U) ||
        !luna_scalar_layout_is_valid(&layout->integer16, 16U) ||
        !luna_scalar_layout_is_valid(&layout->integer32, 32U) ||
        !luna_scalar_layout_is_valid(&layout->integer64, 64U) ||
        !luna_scalar_layout_is_valid(&layout->float32, 32U) ||
        !luna_scalar_layout_is_valid(&layout->float64, 64U)) {
        return false;
    }

    const uint32_t pointer_size = layout->pointer.size_bits;
    if ((pointer_size != 16U && pointer_size != 32U && pointer_size != 64U) ||
        layout->pointer.abi_alignment_bits == 0U ||
        layout->pointer.abi_alignment_bits % 8U != 0U) {
        return false;
    }

    const uint32_t pointer_alignment = layout->pointer.abi_alignment_bits;
    return (pointer_alignment & (pointer_alignment - 1U)) == 0U;
}

bool luna_data_layout_equal(const LunaDataLayout *left,
                            const LunaDataLayout *right) {
    return left != NULL && right != NULL &&
           left->byte_order == right->byte_order &&
           left->boolean.size_bits == right->boolean.size_bits &&
           left->boolean.abi_alignment_bits ==
               right->boolean.abi_alignment_bits &&
           left->integer8.size_bits == right->integer8.size_bits &&
           left->integer8.abi_alignment_bits ==
               right->integer8.abi_alignment_bits &&
           left->integer16.size_bits == right->integer16.size_bits &&
           left->integer16.abi_alignment_bits ==
               right->integer16.abi_alignment_bits &&
           left->integer32.size_bits == right->integer32.size_bits &&
           left->integer32.abi_alignment_bits ==
               right->integer32.abi_alignment_bits &&
           left->integer64.size_bits == right->integer64.size_bits &&
           left->integer64.abi_alignment_bits ==
               right->integer64.abi_alignment_bits &&
           left->float32.size_bits == right->float32.size_bits &&
           left->float32.abi_alignment_bits ==
               right->float32.abi_alignment_bits &&
           left->float64.size_bits == right->float64.size_bits &&
           left->float64.abi_alignment_bits ==
               right->float64.abi_alignment_bits &&
           left->pointer.size_bits == right->pointer.size_bits &&
           left->pointer.abi_alignment_bits ==
               right->pointer.abi_alignment_bits;
}

const LunaScalarLayout *luna_data_layout_integer(const LunaDataLayout *layout,
                                                 uint32_t bit_width) {
    if (layout == NULL) {
        return NULL;
    }

    switch (bit_width) {
    case 8U:
        return &layout->integer8;
    case 16U:
        return &layout->integer16;
    case 32U:
        return &layout->integer32;
    case 64U:
        return &layout->integer64;
    default:
        return NULL;
    }
}

const LunaScalarLayout *luna_data_layout_float(const LunaDataLayout *layout,
                                               uint32_t bit_width) {
    if (layout == NULL) {
        return NULL;
    }

    switch (bit_width) {
    case 32U:
        return &layout->float32;
    case 64U:
        return &layout->float64;
    default:
        return NULL;
    }
}

